package com.merchtool;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Notification;
import net.runelite.client.config.Range;

@ConfigGroup(MerchConfig.GROUP)
public interface MerchConfig extends Config
{
	String GROUP = "merchtool";

	@ConfigSection(name = "Deal finder", description = "Which flips get suggested", position = 0)
	String deals = "deals";


	@ConfigItem(keyName = "minVolume", name = "Min volume / hour", section = deals, position = 0,
		description = "Skip items that trade fewer times than this per hour")
	default int minVolume()
	{
		return 100;
	}

	@ConfigItem(keyName = "maxAgeMinutes", name = "Max price age (min)", section = deals, position = 1,
		description = "Skip items whose last buy or sell price is older than this. 0 = no limit. Old prices make fake margins.")
	default int maxAgeMinutes()
	{
		return 10;
	}

	@ConfigItem(keyName = "hideSpikes", name = "Hide price spikes", section = deals, position = 2,
		description = "Skip items whose latest price is far off the 5-minute or 1-hour average")
	default boolean hideSpikes()
	{
		return true;
	}

	@ConfigItem(keyName = "minPrice", name = "Min item price", section = deals, position = 3,
		description = "e.g. 10k, 1m. Blank = no minimum")
	default String minPrice()
	{
		return "";
	}

	@ConfigItem(keyName = "maxPrice", name = "Max item price", section = deals, position = 4,
		description = "e.g. 50m. Blank = no maximum")
	default String maxPrice()
	{
		return "";
	}

	@ConfigItem(keyName = "f2pOnly", name = "F2P items only", section = deals, position = 5,
		description = "Only suggest items free-to-play accounts can trade")
	default boolean f2pOnly()
	{
		return false;
	}

	@ConfigItem(keyName = "includeBonds", name = "Suggest bonds", section = deals, position = 6,
		description = "Include Old school bonds in the deals. Off by default: they're slow to flip one at a time")
	default boolean includeBonds()
	{
		return false;
	}

	@ConfigItem(keyName = "splitSlots", name = "Split gold across free slots", section = deals, position = 7,
		description = "Size each suggestion to your free gold divided by your empty GE slots, and suggest a different"
			+ " flip for every empty slot, instead of putting everything into one item")
	default boolean splitSlots()
	{
		return false;
	}

	@Range(min = 30, max = 600)
	@ConfigItem(keyName = "refreshSeconds", name = "Price refresh (s)", section = deals, position = 8,
		description = "How often to fetch the latest prices from the OSRS Wiki")
	default int refreshSeconds()
	{
		return 60;
	}


	@Range(min = 1, max = 120)
	@ConfigItem(keyName = "staleMinutes", name = "Slot stale after (min)", section = deals, position = 9,
		description = "In the Slots tab, an offer's timer turns orange when it hasn't filled for this long")
	default int staleMinutes()
	{
		return 5;
	}

	@ConfigSection(name = "Alerts", description = "RuneLite notifications. Nothing is shown inside the game itself", position = 1)
	String alerts = "alerts";

	@ConfigItem(keyName = "limitResetAlert", name = "Buy limit reset", section = alerts, position = 0,
		description = "Notify when an item whose 4-hour buy limit you used up can be bought again")
	default Notification limitResetAlert()
	{
		return Notification.ON;
	}

	@ConfigItem(keyName = "dumpAlert", name = "Price drop", section = alerts, position = 1,
		description = "Notify when a starred item, an item you hold, or an item in your GE slots suddenly sells well under"
			+ " its average for the last hour")
	default Notification dumpAlert()
	{
		return Notification.ON;
	}

	@Range(min = 3, max = 50)
	@ConfigItem(keyName = "dumpPercent", name = "Price drop size (%)", section = alerts, position = 2,
		description = "How far under the last hour's average the insta-sell price has to fall to count as a drop")
	default int dumpPercent()
	{
		return 10;
	}
}

package com.merchtool;

import com.google.gson.Gson;
import com.google.inject.Provides;
import com.merchtool.core.Alerts;
import com.merchtool.core.Gp;
import com.merchtool.core.Ledger;
import com.merchtool.core.Market;
import com.merchtool.core.OfferTracker;
import com.merchtool.core.PriceData;
import com.merchtool.core.Recipes;
import com.merchtool.ui.MerchModel;
import com.merchtool.ui.MerchPanel;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.WorldType;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import okhttp3.OkHttpClient;

@Slf4j
@PluginDescriptor(
	name = "Flipr",
	description = "GE flipping panel: reads your GE offers, ranks live deals after tax, and keeps your profit and loss",
	tags = {"flipping", "merching", "grand exchange", "ge", "profit", "margin"}
)
public class MerchPlugin extends Plugin implements MerchModel
{
	/** Events in the first few ticks after login are the game replaying every slot, not new activity. */
	private static final int LOGIN_TICKS = 2;
	private static final int RECONCILE_AFTER_TICKS = 3;
	/** One price-drop alert per item per this long, so a slow slide doesn't alert every refresh. */
	private static final long DUMP_ALERT_EVERY_MS = 30 * 60_000L;

	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private MerchConfig config;
	@Inject private ConfigManager configManager;
	@Inject private OkHttpClient http;
	@Inject private Gson gson;
	@Inject private ScheduledExecutorService executor;
	@Inject private ClientToolbar clientToolbar;
	@Inject private ItemManager itemManager;
	@Inject private Notifier notifier;

	private WikiPrices prices;
	private ProfileStore store;
	private MerchPanel panel;
	private NavigationButton navButton;
	private ScheduledFuture<?> priceTask;

	// Account state: touched on the client thread, read by the panel under this lock.
	private final Object lock = new Object();
	private String profile;
	private ProfileStore.AccountData account;
	private int loginTick = -1;
	private boolean reconcilePending;
	private boolean dirty;
	private final Deque<GrandExchangeOfferChanged> earlyEvents = new ArrayDeque<>();

	private volatile List<Market.Deal> deals = Collections.emptyList();
	private volatile Map<Recipes.Kind, List<Recipes.Result>> recipes = new EnumMap<>(Recipes.Kind.class);
	private volatile long sessionStart;
	/** Item id to when its last price-drop alert went out. */
	private final Map<Integer, Long> dumpAlerted = new HashMap<>();
	/** Empty GE slots that should each get a suggestion: 1, or every empty slot when splitting gold. */
	private volatile int suggestions = 1;
	/** Item on the GE buy/sell screen right now, or -1 when it isn't open. */
	private volatile int geItem = -1;
	private volatile boolean geSell;
	private volatile String priceStatus = "Loading prices…";

	@Provides
	MerchConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(MerchConfig.class);
	}

	@Override
	public void startUp()
	{
		prices = new WikiPrices(http, gson);
		store = new ProfileStore(configManager, gson);
		panel = new MerchPanel(this, itemManager);
		navButton = NavigationButton.builder()
			.tooltip("Flipr")
			.icon(icon())
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		schedulePrices();
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(this::onLoggedIn);
		}
	}

	@Override
	public void shutDown()
	{
		if (priceTask != null)
		{
			priceTask.cancel(false);
		}
		saveNow();
		SwingUtilities.invokeLater(panel::closeWindow);
		clientToolbar.removeNavigation(navButton);
		synchronized (lock)
		{
			account = null;
			profile = null;
		}
	}

	// ---------------------------------------------------------------- prices

	private void schedulePrices()
	{
		if (priceTask != null)
		{
			priceTask.cancel(false);
		}
		priceTask = executor.scheduleWithFixedDelay(this::refreshPrices, 0, config.refreshSeconds(), TimeUnit.SECONDS);
	}

	private void refreshPrices()
	{
		prices.refresh().whenComplete((d, e) -> {
			if (e == null)
			{
				priceStatus = "Live · " + java.time.LocalTime.now().withNano(0);
			}
			else
			{
				Throwable cause = e.getCause() != null ? e.getCause() : e;
				log.debug("Price refresh failed", cause);
				priceStatus = "Price feed failed: " + cause.getMessage()
					+ (prices.get().isEmpty() ? "" : " (showing last good prices)");
			}
			recomputeDeals();
			if (e == null)
			{
				checkDumps();
			}
		});
	}

	/** Re-rank deals against current prices, free gold and buy limits. Safe from any thread. */
	void recomputeDeals()
	{
		PriceData data = prices.get();
		long free;
		Set<Integer> exclude = new HashSet<>();
		Ledger ledgerCopy;
		synchronized (lock)
		{
			Ledger l = account == null ? null : account.ledger;
			free = dealCash();
			for (OfferTracker.Slot s : tracker().slots)
			{
				if (s != null && !s.isDone())
				{
					exclude.add(s.itemId);
				}
			}
			ledgerCopy = l;
		}
		long now = System.currentTimeMillis();
		Market.Filters f = filters();
		java.util.function.IntUnaryOperator used = id -> ledgerCopy == null ? 0 : ledgerCopy.limitUsed(id, now);
		deals = data.isEmpty() ? Collections.emptyList() : Market.rank(data, f, free, used, exclude, now / 1000);
		Map<Recipes.Kind, List<Recipes.Result>> r = new EnumMap<>(Recipes.Kind.class);
		if (!data.isEmpty())
		{
			for (Recipes.Kind k : Recipes.Kind.values())
			{
				r.put(k, Recipes.rank(k, data, f, free, used, now / 1000));
			}
		}
		recipes = r;
		refreshPanel();
	}

	Market.Filters filters()
	{
		Market.Filters f = new Market.Filters();
		f.minVolume = config.minVolume();
		f.maxAgeMinutes = config.maxAgeMinutes();
		f.hideSpikes = config.hideSpikes();
		f.f2pOnly = config.f2pOnly();
		f.minPrice = Math.max(0, Gp.parse(config.minPrice()));
		f.maxPrice = Math.max(0, Gp.parse(config.maxPrice()));
		f.includeBonds = config.includeBonds();
		return f;
	}

	/**
	 * Gold one suggestion may spend: free gold, or free gold split across the empty GE slots when that setting
	 * is on. -1 when no bankroll is set. Call under {@link #lock}.
	 */
	long dealCash()
	{
		Ledger l = account == null ? null : account.ledger;
		if (l == null || !l.hasBankroll())
		{
			suggestions = 1;
			return -1;
		}
		long free = Math.max(0, l.freeGold(tracker().totalEscrow()));
		int open = 0;
		int usable = usableSlots();
		for (int i = 0; i < usable && i < account.slots.length; i++)
		{
			open += account.slots[i] == null ? 1 : 0;
		}
		boolean split = config.splitSlots() && open > 1;
		suggestions = split ? open : 1;
		return split ? free / open : free;
	}

	/** 8 slots on a members world, 3 on a free one. */
	private int usableSlots()
	{
		Set<WorldType> types = client.getWorldType();
		return types == null || types.contains(WorldType.MEMBERS) ? OfferTracker.SLOTS : 3;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged e)
	{
		if (!MerchConfig.GROUP.equals(e.getGroup()))
		{
			return;
		}
		if ("refreshSeconds".equals(e.getKey()))
		{
			schedulePrices();
		}
		else
		{
			executor.execute(this::recomputeDeals);
		}
	}

	// ---------------------------------------------------------------- GE offers

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		GameState s = e.getGameState();
		if (s == GameState.LOGGED_IN)
		{
			onLoggedIn();
		}
		else if (s == GameState.LOGIN_SCREEN)
		{
			// Logged out: save and let go, so a different account can log in next.
			saveNow();
			synchronized (lock)
			{
				account = null;
				profile = null;
			}
			sessionStart = 0;
			earlyEvents.clear();
			refreshPanel();
		}
		else if (s == GameState.HOPPING || s == GameState.LOGGING_IN)
		{
			// The game replays all slots after a hop too.
			loginTick = -1;
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged e)
	{
		// RuneLite can learn which account this is just after LOGGED_IN; load then if we couldn't before.
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			onLoggedIn();
		}
	}

	private void onLoggedIn()
	{
		String key = store.currentProfile();
		if (key == null)
		{
			return;
		}
		synchronized (lock)
		{
			if (account == null || !key.equals(profile))
			{
				if (account != null)
				{
					saveNow();
				}
				profile = key;
				account = store.load(key);
				sessionStart = System.currentTimeMillis();
			}
		}
		loginTick = client.getTickCount();
		reconcilePending = true;
		while (!earlyEvents.isEmpty())
		{
			apply(earlyEvents.poll(), true);
		}
		executor.execute(this::recomputeDeals);
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged e)
	{
		if (client.getWorldType().contains(WorldType.SEASONAL))
		{
			return;
		}
		boolean ready;
		synchronized (lock)
		{
			ready = account != null && loginTick >= 0;
		}
		if (!ready)
		{
			// Arrived before the account was known: replay once it is, as part of the login burst.
			earlyEvents.add(e);
			return;
		}
		apply(e, client.getTickCount() - loginTick <= LOGIN_TICKS);
	}

	private void apply(GrandExchangeOfferChanged e, boolean atLogin)
	{
		GrandExchangeOffer o = e.getOffer();
		long now = System.currentTimeMillis();
		OfferTracker.Fill fill;
		synchronized (lock)
		{
			if (account == null)
			{
				return;
			}
			OfferTracker t = tracker();
			fill = t.update(e.getSlot(), o.getItemId(), o.getState().name(), o.getTotalQuantity(), o.getPrice(),
				o.getQuantitySold(), o.getSpent(), atLogin, now);
			if (fill != null)
			{
				if (fill.buy)
				{
					account.ledger.recordBuy(fill.itemId, fill.qty, fill.gold, fill.time);
				}
				else
				{
					account.ledger.recordSell(fill.itemId, fill.qty, fill.gold, fill.time);
				}
			}
			account.slots = t.slots;
			dirty = true;
		}
		if (fill != null)
		{
			executor.execute(this::recomputeDeals);
		}
		else
		{
			refreshPanel();
		}
	}

	@Subscribe
	public void onGameTick(GameTick t)
	{
		int tick = client.getTickCount();
		if (reconcilePending && loginTick >= 0 && tick - loginTick >= RECONCILE_AFTER_TICKS)
		{
			reconcilePending = false;
			reconcileWithClient();
		}
		if (tick % 5 == 0)
		{
			checkLimitResets();
		}
		if (dirty && tick % 10 == 0)
		{
			saveNow();
		}
		watchGeScreen();
	}

	/** Notices which item is on the GE buy/sell screen, so the panel can show prices for it. Reads only. */
	private void watchGeScreen()
	{
		Widget setup = client.getWidget(InterfaceID.GeOffers.SETUP);
		int item = -1;
		boolean sell = false;
		if (setup != null && !setup.isHidden())
		{
			int v = client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH);
			item = v > 0 ? v : -1;
			sell = client.getVarbitValue(VarbitID.GE_NEWOFFER_TYPE) == 1;
		}
		if (item != geItem || sell != geSell)
		{
			geItem = item;
			geSell = sell;
			refreshPanel();
		}
	}

	/** Notifies when an item whose buy limit you used up can be bought again. */
	private void checkLimitResets()
	{
		PriceData data = prices();
		List<Integer> reset;
		synchronized (lock)
		{
			if (account == null)
			{
				return;
			}
			reset = account.ledger.limitResets(System.currentTimeMillis(), id -> {
				PriceData.Item it = data.items.get(id);
				return it == null ? null : it.limit;
			}, Ledger.ALERT_GRACE_MS);
			if (!reset.isEmpty())
			{
				dirty = true;
			}
		}
		for (int id : reset)
		{
			notifier.notify(config.limitResetAlert(), "Flipr: buy limit reset for " + data.name(id) + ". You can buy again.");
		}
		if (!reset.isEmpty())
		{
			executor.execute(this::recomputeDeals);
		}
	}

	/** Notifies when a starred, held or in-slot item suddenly sells well under its hourly average. */
	private void checkDumps()
	{
		PriceData data = prices();
		Set<Integer> watch = new LinkedHashSet<>();
		synchronized (lock)
		{
			if (account == null)
			{
				return;
			}
			watch.addAll(account.starred);
			for (Ledger.Lot lot : account.ledger.lots)
			{
				watch.add(lot.itemId);
			}
			for (OfferTracker.Slot s : account.slots)
			{
				if (s != null && !s.isDone())
				{
					watch.add(s.itemId);
				}
			}
		}
		long now = System.currentTimeMillis();
		for (int id : watch)
		{
			long[] drop = Alerts.dump(data, id, config.dumpPercent(), now / 1000);
			if (drop == null)
			{
				continue;
			}
			synchronized (dumpAlerted)
			{
				Long last = dumpAlerted.get(id);
				if (last != null && now - last < DUMP_ALERT_EVERY_MS)
				{
					continue;
				}
				dumpAlerted.put(id, now);
			}
			long pct = Math.round((1 - (double) drop[0] / drop[1]) * 100);
			String msg = "Flipr: " + data.name(id) + " is selling at " + Gp.full(drop[0]) + ", " + pct
				+ "% under the last hour's average (" + Gp.full(drop[1]) + ").";
			clientThread.invokeLater(() -> notifier.notify(config.dumpAlert(), msg));
		}
	}

	/** Slots collected or emptied on another device show up as EMPTY in the game but not as an event. */
	private void reconcileWithClient()
	{
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers == null)
		{
			return;
		}
		synchronized (lock)
		{
			if (account == null)
			{
				return;
			}
			for (int i = 0; i < offers.length && i < OfferTracker.SLOTS; i++)
			{
				GrandExchangeOffer o = offers[i];
				if (o == null || o.getState() == GrandExchangeOfferState.EMPTY)
				{
					tracker().reconcileEmpty(i);
				}
			}
			dirty = true;
		}
		refreshPanel();
	}

	private void saveNow()
	{
		String json;
		String key;
		synchronized (lock)
		{
			if (account == null || !dirty)
			{
				return;
			}
			account.ledger.compact(System.currentTimeMillis());
			json = gson.toJson(account);
			key = profile;
			dirty = false;
		}
		executor.execute(() -> store.save(key, json));
	}

	// ---------------------------------------------------------------- read by the panel / overlay / helper

	private OfferTracker tracker()
	{
		OfferTracker t = new OfferTracker();
		if (account != null)
		{
			t.slots = account.slots;
		}
		return t;
	}

	@Override
	public Object lock()
	{
		return lock;
	}

	/** Copy of the slots, or null when logged out. Call under {@link #lock()} for a consistent view. */
	@Override
	public OfferTracker.Slot[] slots()
	{
		synchronized (lock)
		{
			return account == null ? null : account.slots.clone();
		}
	}

	@Override
	public Ledger ledger()
	{
		synchronized (lock)
		{
			return account == null ? null : account.ledger;
		}
	}

	@Override
	public long escrow()
	{
		synchronized (lock)
		{
			return tracker().totalEscrow();
		}
	}

	@Override
	public PriceData prices()
	{
		return prices == null ? PriceData.EMPTY : prices.get();
	}

	@Override
	public List<Market.Deal> deals()
	{
		return deals;
	}

	@Override
	public String priceStatus()
	{
		return priceStatus;
	}

	@Override
	public int staleMinutes()
	{
		return config.staleMinutes();
	}

	@Override
	public int suggestions()
	{
		return suggestions;
	}

	@Override
	public int geItem()
	{
		return geItem;
	}

	@Override
	public boolean geSell()
	{
		return geSell;
	}

	/** Market view of one item with this account's free gold and buy limit, or null if there are no prices. */
	@Override
	public Market.Deal market(int itemId)
	{
		long free;
		int used;
		synchronized (lock)
		{
			Ledger l = account == null ? null : account.ledger;
			free = dealCash();
			used = l == null ? 0 : l.limitUsed(itemId, System.currentTimeMillis());
		}
		return Market.evaluate(prices(), itemId, free, used);
	}

	@Override
	public void setBankroll(long gold)
	{
		synchronized (lock)
		{
			if (account == null)
			{
				return;
			}
			account.ledger.setBankroll(gold, System.currentTimeMillis());
			dirty = true;
		}
		saveNow();
		executor.execute(this::recomputeDeals);
	}

	@Override
	public void resetStats()
	{
		synchronized (lock)
		{
			if (account == null)
			{
				return;
			}
			account.ledger.resetStats();
			dirty = true;
		}
		saveNow();
		executor.execute(this::recomputeDeals);
	}

	@Override
	public void forgetHeld(int itemId)
	{
		synchronized (lock)
		{
			if (account == null)
			{
				return;
			}
			account.ledger.forgetHeld(itemId);
			dirty = true;
		}
		executor.execute(this::recomputeDeals);
	}

	@Override
	public List<Recipes.Result> recipes(Recipes.Kind kind)
	{
		List<Recipes.Result> r = recipes.get(kind);
		return r == null ? Collections.emptyList() : r;
	}

	@Override
	public Set<Integer> starred()
	{
		synchronized (lock)
		{
			return account == null ? Collections.emptySet() : new LinkedHashSet<>(account.starred);
		}
	}

	@Override
	public void toggleStar(int itemId)
	{
		synchronized (lock)
		{
			if (account == null)
			{
				return;
			}
			if (!account.starred.remove(itemId))
			{
				account.starred.add(itemId);
			}
			dirty = true;
		}
		refreshPanel();
	}

	@Override
	public CompletableFuture<List<PriceData.Point>> history(int itemId, String step)
	{
		return prices.history(itemId, step);
	}

	@Override
	public long sessionStart()
	{
		return sessionStart;
	}

	public void refreshPanel()
	{
		if (panel != null)
		{
			SwingUtilities.invokeLater(panel::rebuild);
		}
	}


	private static BufferedImage icon()
	{
		BufferedImage img = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(0xFF981F));
		g.fillOval(1, 5, 10, 10);
		g.setColor(new Color(0xFFD94A));
		g.fillOval(5, 1, 10, 10);
		g.setColor(new Color(0x7A5A12));
		g.setStroke(new BasicStroke(1f));
		g.drawOval(5, 1, 10, 10);
		g.dispose();
		return img;
	}
}

package com.merchtool;

import com.google.gson.Gson;
import com.merchtool.core.Ledger;
import com.merchtool.core.OfferTracker;
import java.util.LinkedHashSet;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Saves each account's slots and books in RuneLite's own per-account settings (the "RS profile"),
 * so they follow the account and never touch files directly.
 */
@Slf4j
class ProfileStore
{
	static final class AccountData
	{
		OfferTracker.Slot[] slots = new OfferTracker.Slot[OfferTracker.SLOTS];
		Ledger ledger = new Ledger();
		/** Items you starred in the Deals tab. */
		Set<Integer> starred = new LinkedHashSet<>();
	}

	private static final String KEY = "account";

	private final ConfigManager configManager;
	private final Gson gson;

	ProfileStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	/** The logged-in account's profile key, or null until RuneLite knows which account it is. */
	String currentProfile()
	{
		return configManager.getRSProfileKey();
	}

	AccountData load(String profile)
	{
		String json = configManager.getConfiguration(MerchConfig.GROUP, profile, KEY);
		if (json == null || json.isEmpty())
		{
			return new AccountData();
		}
		try
		{
			AccountData d = gson.fromJson(json, AccountData.class);
			if (d == null)
			{
				return new AccountData();
			}
			if (d.slots == null || d.slots.length != OfferTracker.SLOTS)
			{
				d.slots = new OfferTracker.Slot[OfferTracker.SLOTS];
			}
			if (d.ledger == null)
			{
				d.ledger = new Ledger();
			}
			if (d.starred == null)
			{
				d.starred = new LinkedHashSet<>();
			}
			return d;
		}
		catch (Exception e)
		{
			// Never save over data we couldn't read: keep a copy under another key for recovery.
			log.warn("Couldn't read saved merch data, keeping a backup and starting fresh", e);
			configManager.setConfiguration(MerchConfig.GROUP, profile, KEY + ".unreadable", json);
			return new AccountData();
		}
	}

	/** Saves to the profile the data was loaded from, even if RuneLite has already logged out. */
	void save(String profile, String json)
	{
		configManager.setConfiguration(MerchConfig.GROUP, profile, KEY, json);
	}
}

package com.merchtool;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.reflect.TypeToken;
import com.merchtool.core.PriceData;
import java.io.IOException;
import java.lang.reflect.Type;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Fetches the OSRS Wiki real-time price API (the same RuneLite-fed data the web tool uses).
 * Requests run on OkHttp's own threads via enqueue(), never on the client thread.
 */
class WikiPrices
{
	private static final String API = "https://prices.runescape.wiki/api/v1/osrs";
	// The wiki blocks generic user agents and asks every client to say what it is.
	private static final String USER_AGENT = "Flipr RuneLite plugin - GE flipping panel";
	private static final long AVERAGES_EVERY_MS = 5 * 60_000L;
	private static final long MAPPING_EVERY_MS = 6 * 3600_000L;

	private final OkHttpClient http;
	private final Gson gson;

	private volatile PriceData data = PriceData.EMPTY;
	private volatile long averagesAt;
	private volatile long mappingAt;
	private volatile boolean inFlight;

	WikiPrices(OkHttpClient http, Gson gson)
	{
		this.http = http;
		this.gson = gson;
	}

	PriceData get()
	{
		return data;
	}

	/**
	 * Starts a refresh. The averages and item list refresh less often than /latest.
	 * Completes when the new snapshot is in place, or exceptionally if a request failed (old data is kept).
	 */
	CompletableFuture<PriceData> refresh()
	{
		if (inFlight)
		{
			return CompletableFuture.completedFuture(data);
		}
		inFlight = true;
		long now = System.currentTimeMillis();
		PriceData old = data;
		boolean needMapping = old.items.isEmpty() || now - mappingAt > MAPPING_EVERY_MS;
		boolean needAverages = old.avg5m.isEmpty() || now - averagesAt > AVERAGES_EVERY_MS;

		CompletableFuture<String> mapping = needMapping ? fetch("/mapping") : CompletableFuture.completedFuture(null);
		CompletableFuture<String> a5 = needAverages ? fetch("/5m") : CompletableFuture.completedFuture(null);
		CompletableFuture<String> a1 = needAverages ? fetch("/1h") : CompletableFuture.completedFuture(null);
		CompletableFuture<String> latest = fetch("/latest");

		return CompletableFuture.allOf(mapping, a5, a1, latest).thenApply(v -> {
			Map<Integer, PriceData.Item> items = old.items;
			if (needMapping)
			{
				Type t = new TypeToken<List<PriceData.Item>>()
				{
				}.getType();
				List<PriceData.Item> list = gson.fromJson(mapping.join(), t);
				Map<Integer, PriceData.Item> m = new HashMap<>();
				for (PriceData.Item it : list)
				{
					m.put(it.id, it);
				}
				items = m;
				mappingAt = now;
			}
			Map<Integer, PriceData.Avg> avg5 = old.avg5m;
			Map<Integer, PriceData.Avg> avg1 = old.avg1h;
			if (needAverages)
			{
				avg5 = dataMap(a5.join(), PriceData.Avg.class);
				avg1 = dataMap(a1.join(), PriceData.Avg.class);
				averagesAt = now;
			}
			data = new PriceData(items, dataMap(latest.join(), PriceData.Latest.class), avg5, avg1, now / 1000);
			return data;
		}).whenComplete((d, e) -> inFlight = false);
	}

	/**
	 * Price history for one item.
	 *
	 * @param step "5m" (about 30 hours), "1h" (about 2 weeks) or "6h" (about 3 months)
	 */
	CompletableFuture<List<PriceData.Point>> history(int itemId, String step)
	{
		return fetch("/timeseries?timestep=" + step + "&id=" + itemId).thenApply(json -> {
			Type t = new TypeToken<List<PriceData.Point>>()
			{
			}.getType();
			List<PriceData.Point> points = gson.fromJson(gson.fromJson(json, JsonObject.class).get("data"), t);
			return points == null ? Collections.<PriceData.Point>emptyList() : points;
		});
	}

	private <T> Map<Integer, T> dataMap(String json, Class<T> type)
	{
		JsonObject obj = gson.fromJson(json, JsonObject.class).getAsJsonObject("data");
		Map<Integer, T> out = new HashMap<>(obj.size() * 2);
		obj.entrySet().forEach(e -> out.put(Integer.parseInt(e.getKey()), gson.fromJson(e.getValue(), type)));
		return out;
	}

	private CompletableFuture<String> fetch(String path)
	{
		CompletableFuture<String> f = new CompletableFuture<>();
		Request req = new Request.Builder().url(API + path).header("User-Agent", USER_AGENT).build();
		http.newCall(req).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				f.completeExceptionally(e);
			}

			@Override
			public void onResponse(Call call, Response res)
			{
				try (Response r = res)
				{
					ResponseBody body = r.body();
					if (!r.isSuccessful() || body == null)
					{
						f.completeExceptionally(new IOException(path + " returned HTTP " + r.code()));
						return;
					}
					f.complete(body.string());
				}
				catch (IOException e)
				{
					f.completeExceptionally(e);
				}
			}
		});
		return f;
	}
}

package com.merchtool.core;

/**
 * Suggests what to do with a live GE offer that isn't going well: re-price it, or cancel it. Advice only: the
 * plugin never changes an offer itself.
 */
public final class Advice
{
	public static final class Tip
	{
		public final String text;
		/** True when acting now matters: outbid, undercut, or the margin is gone. */
		public final boolean urgent;

		Tip(String text, boolean urgent)
		{
			this.text = text;
			this.urgent = urgent;
		}
	}

	private Advice()
	{
	}

	/**
	 * @param d        current market for the slot's item, or null when there are no prices
	 * @param avgCost  what you paid per item still held (sell offers), or 0 when unknown
	 * @param staleMs  how long without a fill counts as stale
	 * @return a tip, or null when the offer looks fine
	 */
	public static Tip forSlot(OfferTracker.Slot s, Market.Deal d, long avgCost, long now, long staleMs)
	{
		if (s == null || d == null || s.isDone())
		{
			return null;
		}
		boolean stale = now - s.lastActivity > staleMs;
		String idle = Gp.duration(now - s.lastActivity);
		if (s.buy)
		{
			long keep = GeTax.afterTax(s.itemId, d.offerSell);
			long atYourPrice = keep - s.price;
			boolean outbid = d.buy > s.price;
			if (outbid)
			{
				return d.margin > 0
					? new Tip("Outbid. Re-place at " + Gp.full(d.offerBuy) + " (still " + Gp.signed(d.margin) + " ea)", true)
					: new Tip("Outbid, and paying more leaves no profit. Cancel?", true);
			}
			if (atYourPrice <= 0)
			{
				return new Tip("The sell price fell: this buy no longer makes a profit. Cancel?", true);
			}
			if (stale && d.offerBuy > s.price && d.margin > 0)
			{
				return new Tip("No fills for " + idle + ". Try " + Gp.full(d.offerBuy) + " (" + Gp.signed(d.margin) + " ea)", false);
			}
			return null;
		}
		boolean undercut = d.sell < s.price;
		if (undercut || stale && d.offerSell < s.price)
		{
			String head = undercut ? "Undercut. Re-list at " : "No fills for " + idle + ". Try ";
			String tail = "";
			if (avgCost > 0)
			{
				long each = GeTax.afterTax(s.itemId, d.offerSell) - avgCost;
				tail = each >= 0 ? " (still " + Gp.signed(each) + " ea)" : " (loses " + Gp.full(-each) + " ea, or wait)";
			}
			return new Tip(head + Gp.full(d.offerSell) + tail, undercut);
		}
		return null;
	}
}

package com.merchtool.core;

/** Spots a sudden price drop ("dump") on an item you care about. */
public final class Alerts
{
	/** Fewer insta-sells than this in the last hour and the average means little. */
	static final long MIN_HOUR_SELLS = 5;
	/** Ignore a "latest" price older than this: it's history, not a dump. */
	static final long MAX_AGE_SEC = 10 * 60;

	private Alerts()
	{
	}

	/**
	 * @param percent how far under the hour's average counts as a dump, e.g. 10
	 * @return {latest insta-sell price, hour's average insta-sell price}, or null when there's no dump
	 */
	public static long[] dump(PriceData data, int itemId, int percent, long nowSec)
	{
		PriceData.Latest l = data.latest.get(itemId);
		PriceData.Avg a = data.avg1h.get(itemId);
		if (percent <= 0 || l == null || a == null || l.low == null || l.lowTime == null || a.avgLowPrice == null
			|| a.avgLowPrice <= 0 || a.lowPriceVolume < MIN_HOUR_SELLS || nowSec - l.lowTime > MAX_AGE_SEC)
		{
			return null;
		}
		return l.low * 100 <= a.avgLowPrice * (100 - percent) ? new long[]{l.low, a.avgLowPrice} : null;
	}
}

package com.merchtool.core;

import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.List;
import java.util.Locale;

/** Flips as CSV text, for pasting into a spreadsheet. */
public final class Csv
{
	private static final DateTimeFormatter TIME = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss", Locale.US);

	private Csv()
	{
	}

	public static String flips(List<Ledger.Flip> flips, PriceData data, ZoneId zone)
	{
		StringBuilder b = new StringBuilder("Sold at,Bought from,Item,Quantity,Cost,Sold for,Tax,Profit\n");
		for (Ledger.Flip f : flips)
		{
			b.append(TIME.format(Instant.ofEpochMilli(f.time).atZone(zone))).append(',')
				.append(f.boughtAt > 0 ? TIME.format(Instant.ofEpochMilli(f.boughtAt).atZone(zone)) : "").append(',')
				.append(quote(data.name(f.itemId))).append(',')
				.append(f.qty).append(',')
				.append(f.cost).append(',')
				.append(f.revenue).append(',')
				.append(f.tax).append(',')
				.append(f.profit).append('\n');
		}
		return b.toString();
	}

	private static String quote(String s)
	{
		return s.contains(",") || s.contains("\"") ? "\"" + s.replace("\"", "\"\"") + "\"" : s;
	}
}

/*
 * Tax rules and exempt item lists adapted from Flipping Utilities
 * (https://github.com/Flipping-Utilities/rl-plugin), Copyright (c) 2020, Belieal. BSD 2-Clause License.
 * Credited in README.md.
 */
package com.merchtool.core;

import java.util.Set;
import net.runelite.api.gameval.ItemID;

/** Grand Exchange tax: 2% of the sell price per item, rounded down, capped at 5m (since 29 May 2025). */
public final class GeTax
{
	public static final long CAP = 5_000_000L;

	/** Exempt since the tax was introduced: bonds and starter tools. */
	private static final Set<Integer> EXEMPT = Set.of(
		ItemID.CHISEL, ItemID.GARDENING_TROWEL, ItemID.HAMMER, ItemID.NEEDLE, ItemID.OSRS_BOND,
		ItemID.PESTLE_AND_MORTAR, ItemID.RAKE, ItemID.POH_SAW, ItemID.SECATEURS, ItemID.DIBBER,
		ItemID.SHEARS, ItemID.SPADE, ItemID.WATERING_CAN_0);

	/** Made exempt on 29 May 2025, when the rate went from 1% to 2%. */
	private static final Set<Integer> EXEMPT_2025 = Set.of(
		ItemID.POH_TABLET_ARDOUGNETELEPORT, ItemID.BASS, ItemID.BREAD, ItemID.BRONZE_ARROW, ItemID.BRONZE_DART,
		ItemID.CAKE, ItemID.POH_TABLET_CAMELOTTELEPORT, ItemID.POH_TABLET_FORTISTELEPORT, ItemID.COOKED_CHICKEN,
		ItemID.COOKED_MEAT, ItemID._4DOSE1ENERGY, ItemID._3DOSE1ENERGY, ItemID._2DOSE1ENERGY, ItemID._1DOSE1ENERGY,
		ItemID.POH_TABLET_FALADORTELEPORT, ItemID.NECKLACE_OF_MINIGAMES_8, ItemID.HERRING, ItemID.IRON_ARROW,
		ItemID.IRON_DART, ItemID.POH_TABLET_KOURENDTELEPORT, ItemID.LOBSTER, ItemID.POH_TABLET_LUMBRIDGETELEPORT,
		ItemID.MACKEREL, ItemID.MEAT_PIE, ItemID.MINDRUNE, ItemID.PIKE, ItemID.RING_OF_DUELING_8, ItemID.SALMON,
		ItemID.SHRIMP, ItemID.STEEL_ARROW, ItemID.STEEL_DART, ItemID.POH_TABLET_TELEPORTTOHOUSE, ItemID.TUNA,
		ItemID.POH_TABLET_VARROCKTELEPORT);

	private GeTax()
	{
	}

	public static boolean isExempt(int itemId)
	{
		return EXEMPT.contains(itemId) || EXEMPT_2025.contains(itemId);
	}

	/** Tax on one item sold at {@code price}. price / 50 is exactly floor(price * 2%). */
	public static long perItem(int itemId, long price)
	{
		if (price <= 0 || isExempt(itemId))
		{
			return 0;
		}
		return Math.min(price / 50, CAP);
	}

	/** What you keep per item after tax. */
	public static long afterTax(int itemId, long price)
	{
		return price - perItem(itemId, price);
	}
}

package com.merchtool.core;

import java.text.NumberFormat;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Gold amounts: GE-style short form (12.5K, 3.42M) and parsing of what people type ("1.5m", "250k"). */
public final class Gp
{
	private static final Pattern INPUT = Pattern.compile("^(-?\\d*\\.?\\d+)\\s*([kmb])?$");

	private Gp()
	{
	}

	public static String full(long n)
	{
		return NumberFormat.getIntegerInstance(Locale.US).format(n);
	}

	public static String shortForm(long n)
	{
		long a = Math.abs(n);
		String s = n < 0 ? "-" : "";
		if (a >= 1_000_000_000L)
		{
			return s + trim(a / 1e9, a >= 10_000_000_000L ? 1 : 2) + "B";
		}
		if (a >= 10_000_000L)
		{
			return s + trim(a / 1e6, 1) + "M";
		}
		if (a >= 1_000_000L)
		{
			return s + trim(a / 1e6, 2) + "M";
		}
		if (a >= 100_000L)
		{
			return s + Math.round(a / 1e3) + "K";
		}
		if (a >= 10_000L)
		{
			return s + trim(a / 1e3, 1) + "K";
		}
		return s + full(a);
	}

	public static String signed(long n)
	{
		return (n > 0 ? "+" : "") + shortForm(n);
	}

	private static String trim(double v, int decimals)
	{
		return String.format(Locale.US, "%." + decimals + "f", v);
	}

	/** Returns -1 when the text isn't a gold amount. */
	public static long parse(String text)
	{
		if (text == null)
		{
			return -1;
		}
		Matcher m = INPUT.matcher(text.trim().toLowerCase(Locale.US).replace(",", ""));
		if (!m.matches())
		{
			return -1;
		}
		double v = Double.parseDouble(m.group(1));
		String unit = m.group(2);
		if (unit != null)
		{
			v *= unit.equals("k") ? 1e3 : unit.equals("m") ? 1e6 : 1e9;
		}
		return Math.round(v);
	}

	public static String duration(long millis)
	{
		long s = Math.max(0, millis / 1000);
		if (s < 60)
		{
			return s + "s";
		}
		if (s < 3600)
		{
			return (s / 60) + "m " + (s % 60) + "s";
		}
		return (s / 3600) + "h " + ((s % 3600) / 60) + "m";
	}
}

package com.merchtool.core;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;

/**
 * Your books: items bought and not yet sold (lots), completed flips with profit after tax, buy-limit windows,
 * and the bankroll you're merching with. Sells are matched to the oldest buys of the same item first.
 */
public final class Ledger
{
	public static final long LIMIT_WINDOW_MS = 4 * 3600_000L;

	public static final class Lot
	{
		public int itemId;
		public long qty;
		/** Total gold paid for the qty still held. */
		public long cost;
		public long time;
	}

	public static final class Flip
	{
		public long time;
		/** When the earliest of the matched buys filled. 0 in data saved before this was recorded. */
		public long boughtAt;
		public int itemId;
		public long qty;
		public long cost;
		/** Gold received before tax. */
		public long revenue;
		public long tax;
		public long profit;
	}

	public static final class Window
	{
		public long start;
		public int bought;
		/** Set once the "limit reset" alert has gone out for this window. */
		public boolean alerted;
	}

	/** Totals for a stretch of time, for the Stats tab. */
	public static final class Summary
	{
		public long profit;
		public long cost;
		public long tax;
		public int flips;
		public int wins;
		public int losses;
		/** Earliest buy behind any flip in the range, or 0. */
		public long firstBuy;
		/** Item id to {profit, qty sold, flips}, kept flips only. */
		public Map<Integer, long[]> byItem = new HashMap<>();
		/** Flips in the range, oldest first. */
		public List<Flip> list = new ArrayList<>();

		/** Profit per hour between {@code start} and {@code now}; 0 until a few minutes have passed. */
		public long perHour(long start, long now)
		{
			long ms = now - start;
			return start <= 0 || ms < 5 * 60_000L ? 0 : profit * 3600_000L / ms;
		}

		/** Profit as a percentage of what the items cost. */
		public double roi()
		{
			return cost <= 0 ? 0 : profit * 100.0 / cost;
		}
	}

	/** Gold you said you're merching with, and when you said it. */
	public long bankrollStart;
	public long bankrollSince;
	public List<Lot> lots = new ArrayList<>();
	public List<Flip> flips = new ArrayList<>();
	public Map<Integer, Window> limits = new HashMap<>();
	/** Items sold that the plugin never saw you buy (owned before, or bought on another device). */
	public long untrackedSold;

	/** Flips older than the newest {@link #KEEP_FLIPS}, folded into totals so saved data stays small. */
	public long archivedProfit;
	public long archivedSinceBankroll;
	public int archivedWins;
	public int archivedLosses;

	public static final int KEEP_FLIPS = 500;
	/** How late a "limit reset" alert may still go out, e.g. when the reset happened during a world hop. */
	public static final long ALERT_GRACE_MS = 10 * 60_000L;

	public void recordBuy(int itemId, long qty, long gold, long time)
	{
		if (qty <= 0)
		{
			return;
		}
		Lot lot = new Lot();
		lot.itemId = itemId;
		lot.qty = qty;
		lot.cost = gold;
		lot.time = time;
		lots.add(lot);

		Window w = limits.get(itemId);
		if (w == null || time - w.start >= LIMIT_WINDOW_MS)
		{
			w = new Window();
			w.start = time;
			limits.put(itemId, w);
		}
		w.bought += (int) Math.min(Integer.MAX_VALUE, qty);
	}

	/**
	 * @param gross gold received before tax
	 * @return the flip for the part that matched earlier buys, or null if none did
	 */
	public Flip recordSell(int itemId, long qty, long gross, long time)
	{
		if (qty <= 0)
		{
			return null;
		}
		// Tax is per item on the sale price. A fill can mix prices, so work from its average.
		long totalTax = GeTax.perItem(itemId, gross / qty) * qty;
		long matched = 0;
		long cost = 0;
		long boughtAt = 0;
		for (Iterator<Lot> it = lots.iterator(); it.hasNext() && matched < qty; )
		{
			Lot lot = it.next();
			if (lot.itemId != itemId)
			{
				continue;
			}
			long take = Math.min(lot.qty, qty - matched);
			boughtAt = boughtAt == 0 ? lot.time : Math.min(boughtAt, lot.time);
			long takeCost = lot.cost * take / lot.qty;
			lot.qty -= take;
			lot.cost -= takeCost;
			matched += take;
			cost += takeCost;
			if (lot.qty == 0)
			{
				it.remove();
			}
		}
		untrackedSold += qty - matched;
		if (matched == 0)
		{
			return null;
		}
		Flip f = new Flip();
		f.time = time;
		f.boughtAt = boughtAt;
		f.itemId = itemId;
		f.qty = matched;
		f.cost = cost;
		f.revenue = gross * matched / qty;
		f.tax = totalTax * matched / qty;
		f.profit = f.revenue - f.tax - f.cost;
		flips.add(f);
		return f;
	}

	public int limitUsed(int itemId, long now)
	{
		Window w = limits.get(itemId);
		return w == null || now - w.start >= LIMIT_WINDOW_MS ? 0 : w.bought;
	}

	/** Epoch millis the item's buy limit resets, or 0 if there's no active window. */
	public long limitResetsAt(int itemId, long now)
	{
		Window w = limits.get(itemId);
		return w == null || now - w.start >= LIMIT_WINDOW_MS ? 0 : w.start + LIMIT_WINDOW_MS;
	}

	public long heldQty(int itemId)
	{
		long q = 0;
		for (Lot l : lots)
		{
			if (l.itemId == itemId)
			{
				q += l.qty;
			}
		}
		return q;
	}

	/** Average cost per item still held, or 0. */
	public long heldAvgCost(int itemId)
	{
		long q = 0;
		long c = 0;
		for (Lot l : lots)
		{
			if (l.itemId == itemId)
			{
				q += l.qty;
				c += l.cost;
			}
		}
		return q == 0 ? 0 : c / q;
	}

	public long heldCost()
	{
		long c = 0;
		for (Lot l : lots)
		{
			c += l.cost;
		}
		return c;
	}

	/** Stop counting held items you've used, dropped or moved off the GE. */
	public void forgetHeld(int itemId)
	{
		lots.removeIf(l -> l.itemId == itemId);
	}

	/** Profit of kept flips since {@code since}; pass 0 for all time (archived flips included). */
	public long profitSince(long since)
	{
		long p = since <= 0 ? archivedProfit : 0;
		for (Flip f : flips)
		{
			if (f.time >= since)
			{
				p += f.profit;
			}
		}
		return p;
	}

	/**
	 * Totals for flips that finished at or after {@code since}. With {@code since <= 0} the profit, wins and losses
	 * include flips already folded away by {@link #compact}; the per-item breakdown and list cover kept flips only.
	 */
	public Summary summary(long since)
	{
		Summary s = new Summary();
		if (since <= 0)
		{
			s.profit = archivedProfit;
			s.wins = archivedWins;
			s.losses = archivedLosses;
			s.flips = archivedWins + archivedLosses;
		}
		for (Flip f : flips)
		{
			if (f.time < since)
			{
				continue;
			}
			s.list.add(f);
			s.profit += f.profit;
			s.cost += f.cost;
			s.tax += f.tax;
			s.flips++;
			s.wins += f.profit > 0 ? 1 : 0;
			s.losses += f.profit < 0 ? 1 : 0;
			long bought = f.boughtAt > 0 ? f.boughtAt : f.time;
			s.firstBuy = s.firstBuy == 0 ? bought : Math.min(s.firstBuy, bought);
			long[] v = s.byItem.computeIfAbsent(f.itemId, k -> new long[3]);
			v[0] += f.profit;
			v[1] += f.qty;
			v[2]++;
		}
		return s;
	}

	/**
	 * Items whose buy limit you used up and that reset within the last {@code graceMs}. Each window is reported once.
	 * Windows that ran out longer ago (say, while you were logged out) are skipped rather than alerted late.
	 */
	public List<Integer> limitResets(long now, java.util.function.IntFunction<Integer> limitOf, long graceMs)
	{
		List<Integer> out = new ArrayList<>();
		for (Map.Entry<Integer, Window> e : limits.entrySet())
		{
			Window w = e.getValue();
			long resetAt = w.start + LIMIT_WINDOW_MS;
			if (w.alerted || now < resetAt)
			{
				continue;
			}
			w.alerted = true;
			Integer limit = limitOf.apply(e.getKey());
			if (limit != null && limit > 0 && w.bought >= limit && now - resetAt <= graceMs)
			{
				out.add(e.getKey());
			}
		}
		return out;
	}

	public void setBankroll(long gold, long now)
	{
		bankrollStart = gold;
		bankrollSince = now;
		archivedSinceBankroll = 0;
	}

	/**
	 * Wipes flips, profit totals and the bankroll back to nothing. Held items and buy-limit windows stay: they track
	 * items you still own and the game's real 4-hour limits.
	 */
	public void resetStats()
	{
		flips.clear();
		archivedProfit = 0;
		archivedSinceBankroll = 0;
		archivedWins = 0;
		archivedLosses = 0;
		untrackedSold = 0;
		bankrollStart = 0;
		bankrollSince = 0;
	}

	public boolean hasBankroll()
	{
		return bankrollStart > 0;
	}

	/** Starting gold plus every profit or loss since. */
	public long bankroll()
	{
		long p = archivedSinceBankroll;
		for (Flip f : flips)
		{
			if (f.time >= bankrollSince)
			{
				p += f.profit;
			}
		}
		return bankrollStart + p;
	}

	public int wins()
	{
		int n = archivedWins;
		for (Flip f : flips)
		{
			n += f.profit > 0 ? 1 : 0;
		}
		return n;
	}

	public int losses()
	{
		int n = archivedLosses;
		for (Flip f : flips)
		{
			n += f.profit < 0 ? 1 : 0;
		}
		return n;
	}

	/** Fold old flips into totals and drop expired buy-limit windows. Totals stay exact. */
	public void compact(long now)
	{
		while (flips.size() > KEEP_FLIPS)
		{
			Flip f = flips.remove(0);
			archivedProfit += f.profit;
			if (f.time >= bankrollSince)
			{
				archivedSinceBankroll += f.profit;
			}
			archivedWins += f.profit > 0 ? 1 : 0;
			archivedLosses += f.profit < 0 ? 1 : 0;
		}
		// Keep a just-expired window a little longer, so its "limit reset" alert can still go out.
		limits.values().removeIf(w -> now - w.start >= LIMIT_WINDOW_MS + ALERT_GRACE_MS);
	}

	/** Bankroll minus gold in live buy offers and in items you're holding. */
	public long freeGold(long escrow)
	{
		return bankroll() - escrow - heldCost();
	}
}

package com.merchtool.core;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.IntUnaryOperator;
import net.runelite.api.gameval.ItemID;

/**
 * Turns raw prices into flips you can actually do. Same rules as the merch.html Deal Finder:
 * offers go 1gp inside the spread, tax is charged on your real sell price, and prices that are stale or far
 * off the 5-minute / 1-hour averages are flagged as spikes because they make fake margins.
 */
public final class Market
{
	public static final class Deal
	{
		public int itemId;
		public String name;
		public boolean members;
		/** Market prices: buy = last insta-sell, sell = last insta-buy. */
		public long buy;
		public long sell;
		/** The prices you'd put in. */
		public long offerBuy;
		public long offerSell;
		public long tax;
		public long margin;
		public double roi;
		public long volHr;
		public long sellOffsHr;
		/** Epoch seconds of the older of the two prices. */
		public long oldest;
		public boolean spike;
		public Integer limit;
		public int limitLeft;
		public long maxQty;
		public long potProfit;
	}

	public static final class Filters
	{
		public long minVolume = 100;
		public int maxAgeMinutes = 10;
		public boolean hideSpikes = true;
		public boolean f2pOnly;
		public long minPrice;
		public long maxPrice;
		public long minMargin = 1;
		public boolean includeBonds = true;
	}

	private Market()
	{
	}

	/**
	 * @param freeGold   gold available to spend, or a negative number when no bankroll is set (no cash cap)
	 * @param limitUsed  how many of this item you've bought in the current 4-hour window
	 */
	public static Deal evaluate(PriceData data, int itemId, long freeGold, int limitUsed)
	{
		PriceData.Latest l = data.latest.get(itemId);
		PriceData.Item it = data.items.get(itemId);
		if (l == null || it == null || l.high == null || l.low == null || l.high <= 0 || l.low <= 0)
		{
			return null;
		}
		PriceData.Avg a5 = data.avg5m.get(itemId);
		PriceData.Avg a1 = data.avg1h.get(itemId);
		Deal d = new Deal();
		d.itemId = itemId;
		d.name = it.name;
		d.members = it.members;
		d.buy = l.low;
		d.sell = l.high;
		long step = d.sell - d.buy >= 3 ? 1 : 0;
		d.offerBuy = d.buy + step;
		d.offerSell = d.sell - step;
		d.tax = GeTax.perItem(itemId, d.offerSell);
		d.margin = d.offerSell - d.tax - d.offerBuy;
		d.roi = d.margin * 100.0 / d.offerBuy;
		d.volHr = a1 == null ? 0 : a1.highPriceVolume + a1.lowPriceVolume;
		d.sellOffsHr = a1 == null ? 0 : a1.lowPriceVolume;
		d.oldest = Math.min(l.highTime == null ? 0 : l.highTime, l.lowTime == null ? 0 : l.lowTime);
		d.spike = isSpike(d, a5, a1);
		d.limit = it.limit;
		d.limitLeft = it.limit == null ? Integer.MAX_VALUE : Math.max(0, it.limit - limitUsed);

		long cap = d.limitLeft;
		if (freeGold >= 0)
		{
			cap = Math.min(cap, freeGold / d.offerBuy);
		}
		if (d.sellOffsHr > 0)
		{
			// You won't fill more than about half of what the market sells off in a 4-hour limit window.
			cap = Math.min(cap, Math.max(1, d.sellOffsHr * 4 / 2));
		}
		d.maxQty = cap == Integer.MAX_VALUE ? 0 : Math.max(0, cap);
		d.potProfit = d.margin * d.maxQty;
		return d;
	}

	static boolean isSpike(Deal d, PriceData.Avg a5, PriceData.Avg a1)
	{
		if (a5 != null)
		{
			if (off(d.sell, a5.avgHighPrice, 0.25) || off(d.buy, a5.avgLowPrice, 0.25))
			{
				return true;
			}
		}
		// The 5-minute average can be the spike itself (a burst of panic-buys), so also check the last hour.
		if (a1 != null)
		{
			if (a1.highPriceVolume >= 5 && off(d.sell, a1.avgHighPrice, 0.2))
			{
				return true;
			}
			if (a1.lowPriceVolume >= 5 && off(d.buy, a1.avgLowPrice, 0.2))
			{
				return true;
			}
		}
		// An inverted market (insta-buy below insta-sell) almost always means one price is stale.
		return d.sell < d.buy;
	}

	private static boolean off(long price, Long avg, double tolerance)
	{
		return avg != null && avg > 0 && Math.abs((double) price / avg - 1) > tolerance;
	}

	public static boolean passes(Deal d, Filters f, long nowSec)
	{
		if (d.margin < Math.max(1, f.minMargin) || d.maxQty <= 0 || d.limitLeft <= 0)
		{
			return false;
		}
		if (f.minPrice > 0 && d.buy < f.minPrice || f.maxPrice > 0 && d.buy > f.maxPrice)
		{
			return false;
		}
		if (!f.includeBonds && d.itemId == ItemID.OSRS_BOND)
		{
			return false;
		}
		if (d.volHr < f.minVolume || f.f2pOnly && d.members)
		{
			return false;
		}
		if (f.maxAgeMinutes > 0 && nowSec - d.oldest > f.maxAgeMinutes * 60L)
		{
			return false;
		}
		return !(f.hideSpikes && d.spike);
	}

	/** Every passing deal, best potential profit first. */
	public static List<Deal> rank(PriceData data, Filters f, long freeGold, IntUnaryOperator limitUsed,
		Set<Integer> exclude, long nowSec)
	{
		List<Deal> out = new ArrayList<>();
		for (Map.Entry<Integer, PriceData.Latest> e : data.latest.entrySet())
		{
			int id = e.getKey();
			if (exclude.contains(id))
			{
				continue;
			}
			Deal d = evaluate(data, id, freeGold, limitUsed.applyAsInt(id));
			if (d != null && passes(d, f, nowSec))
			{
				out.add(d);
			}
		}
		out.sort(Comparator.comparingLong((Deal d) -> d.potProfit).reversed().thenComparing(d -> d.name));
		return out;
	}
}

/*
 * Event-screening rules adapted from Flipping Utilities' NewOfferEventPipelineHandler and OfferEvent
 * (https://github.com/Flipping-Utilities/rl-plugin), Copyright (c) 2020, Belieal. BSD 2-Clause License.
 * Credited in README.md.
 */
package com.merchtool.core;

/**
 * Mirrors your 8 GE slots from the game's offer events and reports each new fill.
 *
 * The game's events are noisy: most arrive twice, a completed offer sends a BUYING event and then a BOUGHT
 * event with the same numbers, and logging in replays every slot (often as EMPTY first). Working in deltas
 * against the last known state of each slot absorbs all of that: a repeated event adds zero.
 */
public final class OfferTracker
{
	public static final int SLOTS = 8;

	/** What's in one GE slot. Saved to disk so fills made while logged out are caught on the next login. */
	public static final class Slot
	{
		public int itemId;
		public boolean buy;
		public int total;
		/** The price you listed at. */
		public long price;
		public int filled;
		/** Gold paid (buy) or received before tax (sell) so far. */
		public long spent;
		/** GrandExchangeOfferState name: BUYING, BOUGHT, SELLING, SOLD, CANCELLED_BUY, CANCELLED_SELL. */
		public String state;
		/** Epoch millis the offer was placed, or 0 when it was placed while the plugin wasn't watching. */
		public long placedAt;
		/** Epoch millis of the last fill (or of placement). Drives the slot timer. */
		public long lastActivity;

		public boolean isDone()
		{
			return "BOUGHT".equals(state) || "SOLD".equals(state) || isCancelled();
		}

		public boolean isCancelled()
		{
			return "CANCELLED_BUY".equals(state) || "CANCELLED_SELL".equals(state);
		}

		/** Gold still sitting in an unfilled buy offer. */
		public long escrow()
		{
			return buy && !isDone() ? price * (total - filled) : 0;
		}

		boolean sameOfferAs(int itemId, boolean buy, int total, long price)
		{
			return this.itemId == itemId && this.buy == buy && this.total == total && this.price == price;
		}
	}

	/** Items that changed hands in one slot since the last event. */
	public static final class Fill
	{
		public int slot;
		public int itemId;
		public boolean buy;
		public int qty;
		public long gold;
		public long time;
	}

	public Slot[] slots = new Slot[SLOTS];

	public static boolean isBuyState(String state)
	{
		return "BUYING".equals(state) || "BOUGHT".equals(state) || "CANCELLED_BUY".equals(state);
	}

	/**
	 * Apply one offer event.
	 *
	 * @param atLogin true for the burst of events the game sends while logging in
	 * @return the new fill, or null if nothing changed hands
	 */
	public Fill update(int slot, int itemId, String state, int total, long price, int filled, long spent,
		boolean atLogin, long now)
	{
		if (slot < 0 || slot >= SLOTS)
		{
			return null;
		}
		if (itemId <= 0 || "EMPTY".equals(state))
		{
			// At login every slot reports EMPTY before its real state arrives, so only trust an empty
			// slot once logged in (that's an offer being collected). Login leftovers are reconciled separately.
			if (!atLogin)
			{
				slots[slot] = null;
			}
			return null;
		}
		boolean buy = isBuyState(state);
		Slot prev = slots[slot];
		if (prev != null && prev.sameOfferAs(itemId, buy, total, price))
		{
			int dq = filled - prev.filled;
			long dg = spent - prev.spent;
			prev.state = state;
			if (dq <= 0)
			{
				return null;
			}
			prev.filled = filled;
			prev.spent = spent;
			prev.lastActivity = now;
			return fill(slot, prev, dq, dg, now);
		}

		Slot s = new Slot();
		s.itemId = itemId;
		s.buy = buy;
		s.total = total;
		s.price = price;
		s.filled = filled;
		s.spent = spent;
		s.state = state;
		s.placedAt = atLogin ? 0 : now;
		s.lastActivity = now;
		slots[slot] = s;
		// First sight of an offer at login with nothing saved for the slot: we can't tell which of its
		// fills were already counted, so take it as the starting point. Any other new offer was placed
		// just now, or from another device while we weren't watching, and everything filled so far is new.
		if (filled <= 0 || atLogin && prev == null)
		{
			return null;
		}
		return fill(slot, s, filled, spent, now);
	}

	/** After login settles: a slot the game shows as empty was collected while we weren't watching. */
	public void reconcileEmpty(int slot)
	{
		if (slot >= 0 && slot < SLOTS)
		{
			slots[slot] = null;
		}
	}

	public long totalEscrow()
	{
		long t = 0;
		for (Slot s : slots)
		{
			if (s != null)
			{
				t += s.escrow();
			}
		}
		return t;
	}

	private static Fill fill(int slot, Slot s, int qty, long gold, long now)
	{
		Fill f = new Fill();
		f.slot = slot;
		f.itemId = s.itemId;
		f.buy = s.buy;
		f.qty = qty;
		f.gold = gold;
		f.time = now;
		return f;
	}
}

package com.merchtool.core;

import java.util.Collections;
import java.util.Map;

/** One consistent snapshot of the OSRS Wiki real-time price feeds. Replaced whole on every refresh. */
public final class PriceData
{
	public static final class Item
	{
		public int id;
		public String name;
		public boolean members;
		public Integer limit;
		public Long highalch;
	}

	/** Last insta-buy (high) and insta-sell (low) trade, with epoch-second timestamps. */
	public static final class Latest
	{
		public Long high;
		public Long highTime;
		public Long low;
		public Long lowTime;
	}

	public static final class Avg
	{
		public Long avgHighPrice;
		public long highPriceVolume;
		public Long avgLowPrice;
		public long lowPriceVolume;
	}

	/** One step of an item's price history (/timeseries). Times in epoch seconds; prices null when nothing traded. */
	public static final class Point
	{
		public long timestamp;
		public Long avgHighPrice;
		public Long avgLowPrice;
		public long highPriceVolume;
		public long lowPriceVolume;
	}

	public final Map<Integer, Item> items;
	public final Map<Integer, Latest> latest;
	public final Map<Integer, Avg> avg5m;
	public final Map<Integer, Avg> avg1h;
	/** Epoch seconds when /latest was fetched. */
	public final long fetchedAt;

	public static final PriceData EMPTY = new PriceData(Collections.emptyMap(), Collections.emptyMap(),
		Collections.emptyMap(), Collections.emptyMap(), 0);

	public PriceData(Map<Integer, Item> items, Map<Integer, Latest> latest, Map<Integer, Avg> avg5m,
		Map<Integer, Avg> avg1h, long fetchedAt)
	{
		this.items = items;
		this.latest = latest;
		this.avg5m = avg5m;
		this.avg1h = avg1h;
		this.fetchedAt = fetchedAt;
	}

	public String name(int id)
	{
		Item it = items.get(id);
		return it != null ? it.name : "Item " + id;
	}

	public boolean isEmpty()
	{
		return latest.isEmpty();
	}
}

package com.merchtool.core;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.function.IntUnaryOperator;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.gameval.ItemID;

/**
 * Flips that turn one thing into another before selling: high alching, decanting potions at Bob Barter, and
 * packing or unpacking item sets at a GE clerk. Same price rules as {@link Market}: buy 1gp over the insta-sell
 * price, sell 1gp under the insta-buy price, tax on every item sold, stale and spiky prices skipped.
 */
public final class Recipes
{
