	/** Every profitable recipe of one kind, best potential profit first. */
	public static List<Result> rank(Kind kind, PriceData data, Market.Filters f, long freeGold, IntUnaryOperator limitUsed,
		long nowSec)
	{
		List<Result> candidates;
		switch (kind)
		{
			case ALCH:
				candidates = alchs(data);
				break;
			case DECANT:
				candidates = decants(data);
				break;
			default:
				candidates = sets(data);
		}
		List<Result> out = new ArrayList<>();
		for (Result r : candidates)
		{
			if (price(r, data, f, freeGold, limitUsed, nowSec))
			{
				out.add(r);
			}
		}
		out.sort(Comparator.comparingLong((Result r) -> r.potProfit).reversed().thenComparing(r -> r.name));
		return out;
	}

	static List<Result> alchs(PriceData data)
	{
		List<Result> out = new ArrayList<>();
		for (PriceData.Item it : data.items.values())
		{
			if (it.highalch == null || it.highalch <= 0 || it.id == ItemID.NATURERUNE)
			{
				continue;
			}
			Result r = new Result();
			r.kind = Kind.ALCH;
			r.name = it.name;
			r.how = "High alch for " + Gp.full(it.highalch);
			r.iconId = it.id;
			r.buy.add(new Part(it.id, 1));
			r.buy.add(new Part(ItemID.NATURERUNE, 1));
			r.revenue = it.highalch;
			out.add(r);
		}
		return out;
	}

	static List<Result> decants(PriceData data)
	{
		Map<String, Map<Integer, Integer>> potions = new TreeMap<>();
		for (PriceData.Item it : data.items.values())
		{
			Matcher m = DOSE.matcher(it.name);
			if (m.matches() && !NOT_A_POTION.matcher(it.name).find())
			{
				potions.computeIfAbsent(m.group(1).trim(), k -> new HashMap<>()).put(Integer.parseInt(m.group(2)), it.id);
			}
		}
		List<Result> out = new ArrayList<>();
		for (Map.Entry<String, Map<Integer, Integer>> e : potions.entrySet())
		{
			Integer four = e.getValue().get(4);
			if (four == null)
			{
				continue;
			}
			for (int dose = 1; dose <= 3; dose++)
			{
				Integer from = e.getValue().get(dose);
				if (from == null)
				{
					continue;
				}
				// Same number of doses on both sides: 4 x (3) = 3 x (4), 2 x (2) = 1 x (4), 4 x (1) = 1 x (4).
				int lcm = dose == 3 ? 12 : 4;
				out.add(decant(e.getKey(), from, dose, lcm / dose, four, 4, lcm / 4));
				out.add(decant(e.getKey(), four, 4, lcm / 4, from, dose, lcm / dose));
			}
		}
		return out;
	}

	private static Result decant(String potion, int fromId, int fromDose, int fromQty, int toId, int toDose, int toQty)
	{
		Result r = new Result();
		r.kind = Kind.DECANT;
		r.name = potion + " (" + fromDose + ") to (" + toDose + ")";
		r.how = "Buy " + fromQty + ", decant at Bob Barter, sell " + toQty;
		r.iconId = toId;
		r.buy.add(new Part(fromId, fromQty));
		r.sell.add(new Part(toId, toQty));
		return r;
	}

	static List<Result> sets(PriceData data)
	{
		List<Result> out = new ArrayList<>();
		for (int[] s : SETS)
		{
			boolean known = true;
			for (int id : s)
			{
				known &= data.items.containsKey(id);
			}
			if (!known)
			{
				continue;
			}
			String name = data.name(s[0]);
			Result pack = new Result();
			pack.kind = Kind.SET;
			pack.name = name + ": pack";
			pack.how = "Buy the " + (s.length - 1) + " pieces, swap at a GE clerk, sell the set";
			pack.iconId = s[0];
			pack.sell.add(new Part(s[0], 1));
			Result unpack = new Result();
			unpack.kind = Kind.SET;
			unpack.name = name + ": unpack";
			unpack.how = "Buy the set, swap at a GE clerk, sell the " + (s.length - 1) + " pieces";
			unpack.iconId = s[0];
			unpack.buy.add(new Part(s[0], 1));
			for (int i = 1; i < s.length; i++)
			{
				pack.buy.add(new Part(s[i], 1));
				unpack.sell.add(new Part(s[i], 1));
			}
			out.add(pack);
			out.add(unpack);
		}
		return out;
	}

	/** Fills in the money side of a recipe. False when a price is missing, stale or spiky, or it loses money. */
	static boolean price(Result r, PriceData data, Market.Filters f, long freeGold, IntUnaryOperator limitUsed, long nowSec)
	{
		long cap = r.kind == Kind.ALCH ? ALCHS_PER_WINDOW : Long.MAX_VALUE;
		long vol = Long.MAX_VALUE;
		int maxAge = r.kind == Kind.SET && f.maxAgeMinutes > 0 ? Math.max(f.maxAgeMinutes, SET_MAX_AGE_MINUTES) : f.maxAgeMinutes;
		long cost = 0;
		long revenue = r.kind == Kind.ALCH ? r.revenue : 0;
		for (Part p : r.buy)
		{
			Market.Deal d = usable(data, p.itemId, f, maxAge, limitUsed, nowSec);
			if (d == null)
			{
				return false;
			}
			cost += d.offerBuy * p.qty;
			if (d.limit != null)
			{
				cap = Math.min(cap, d.limitLeft / p.qty);
			}
			// You won't fill more than about half of what the market sells off in a 4-hour limit window.
			cap = Math.min(cap, Math.max(1, d.sellOffsHr * 2) / p.qty);
			vol = Math.min(vol, d.volHr);
		}
		for (Part p : r.sell)
		{
			Market.Deal d = usable(data, p.itemId, f, maxAge, limitUsed, nowSec);
			if (d == null)
			{
				return false;
			}
			revenue += GeTax.afterTax(p.itemId, d.offerSell) * p.qty;
			cap = Math.min(cap, Math.max(1, (d.volHr - d.sellOffsHr) * 2) / p.qty);
			vol = Math.min(vol, d.volHr);
		}
		if (cost <= 0)
		{
			return false;
		}
		if (freeGold >= 0)
		{
			cap = Math.min(cap, freeGold / cost);
		}
		r.cost = cost;
		r.revenue = revenue;
		r.profit = revenue - cost;
		r.roi = r.profit * 100.0 / cost;
		r.volHr = vol;
		r.batches = cap == Long.MAX_VALUE ? 0 : Math.max(0, cap);
		r.potProfit = r.profit * r.batches;
		return r.profit >= Math.max(1, f.minMargin) && r.batches > 0;
	}

	/** Market view of one part if it passes the price filters (volume aside), else null. */
	private static Market.Deal usable(PriceData data, int itemId, Market.Filters f, int maxAge, IntUnaryOperator limitUsed,
		long nowSec)
	{
		Market.Deal d = Market.evaluate(data, itemId, -1, limitUsed.applyAsInt(itemId));
		if (d == null || d.volHr < MIN_VOLUME || f.f2pOnly && d.members)
		{
			return null;
		}
		if (maxAge > 0 && nowSec - d.oldest > maxAge * 60L)
		{
			return null;
		}
		return f.hideSpikes && d.spike ? null : d;
	}
}

package com.merchtool.ui;

import com.merchtool.core.Market;
import java.util.Comparator;

/** Ways to order the deals list, biggest first. */
enum DealSort
{
	POTENTIAL("Potential profit", Comparator.comparingLong(d -> d.potProfit)),
	MARGIN("Profit each", Comparator.comparingLong(d -> d.margin)),
	ROI("ROI %", Comparator.comparingDouble(d -> d.roi)),
	VOLUME("Volume / hour", Comparator.comparingLong(d -> d.volHr)),
	PRICE("Item price", Comparator.comparingLong(d -> d.buy));

	private final String label;
	final Comparator<Market.Deal> order;

	DealSort(String label, Comparator<Market.Deal> ascending)
	{
		this.label = label;
		this.order = ascending.reversed().thenComparing(d -> d.name);
	}

	@Override
	public String toString()
	{
		return label;
	}
}

