	// ---------------------------------------------------------------- summary

	private void rebuildSummary()
	{
		summary.removeAll();
		Ledger l = plugin.ledger();
		if (l == null)
		{
			summary.add(stat("Bankroll", "—", "log in", null));
			for (String s : new String[]{"Free to spend", "In offers", "Held items", "Today", "All time"})
			{
				summary.add(stat(s, "—", "", null));
			}
			summary.revalidate();
			return;
		}
		long escrow = plugin.escrow();
		long today = LocalDate.now().atStartOfDay(ZoneId.systemDefault()).toInstant().toEpochMilli();
		long todayP;
		long allP;
		long held;
		long heldQty = 0;
		int flipsToday = 0;
		int wins;
		int losses;
		synchronized (plugin.lock())
		{
			todayP = l.profitSince(today);
			allP = l.profitSince(0);
			held = l.heldCost();
			for (Ledger.Lot lot : l.lots)
			{
				heldQty += lot.qty;
			}
			for (Ledger.Flip f : l.flips)
			{
				flipsToday += f.time >= today ? 1 : 0;
			}
			wins = l.wins();
			losses = l.losses();
		}
		if (l.hasBankroll())
		{
			long change = l.bankroll() - l.bankrollStart;
			long free = l.freeGold(escrow);
			summary.add(stat("Bankroll", Gp.full(l.bankroll()),
				change == 0 ? "started " + Gp.shortForm(l.bankrollStart) : Gp.signed(change) + " since set", null));
			summary.add(stat("Free to spend", Gp.full(free), "sizes the deals", free < 0 ? BAD : GOOD));
		}
		else
		{
			summary.add(stat("Bankroll", "Not set", "type it in on the right", WARN));
			summary.add(stat("Free to spend", "—", "", null));
		}
		summary.add(stat("In offers", Gp.full(escrow), "unfilled buys", null));
		summary.add(stat("Held items", Gp.full(held), Gp.full(heldQty) + " items, paid", null));
		summary.add(stat("Today", Gp.signed(todayP), flipsToday + " flips", colorOf(todayP)));
		summary.add(stat("All time", Gp.signed(allP), wins + " won · " + losses + " lost", colorOf(allP)));
		summary.revalidate();
		summary.repaint();
	}

	private static JPanel stat(String label, String value, String sub, Color color)
	{
		JPanel t = new JPanel();
		t.setLayout(new BoxLayout(t, BoxLayout.Y_AXIS));
		t.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		t.setBorder(new EmptyBorder(6, 10, 6, 10));
		t.add(text(label.toUpperCase(Locale.US), FontManager.getRunescapeSmallFont(), MUTED));
		t.add(text(value, FontManager.getRunescapeBoldFont().deriveFont(18f), color != null ? color : Color.WHITE));
		t.add(text(sub.isEmpty() ? " " : sub, FontManager.getRunescapeSmallFont(), MUTED));
		return t;
	}

	// ---------------------------------------------------------------- GE slots

	private void rebuildSlots()
	{
		slots.removeAll();
		OfferTracker.Slot[] s = plugin.slots();
		List<Market.Deal> deals = plugin.deals();
		int suggested = 0;
		int wanted = plugin.suggestions();
		long now = System.currentTimeMillis();
		for (int i = 0; i < OfferTracker.SLOTS; i++)
		{
			OfferTracker.Slot slot = s == null ? null : s[i];
			if (slot != null)
			{
				slots.add(filledSlot(slot, now));
			}
			else
			{
				Market.Deal next = null;
				if (s != null && suggested < wanted && suggested < deals.size())
				{
					next = deals.get(suggested++);
				}
				slots.add(emptySlot(s == null, next));
			}
		}
		slots.revalidate();
		slots.repaint();
	}

	private JPanel emptySlot(boolean loggedOut, Market.Deal next)
	{
		GeSlot c = new GeSlot();
		c.add(slotHeader("Empty"), BorderLayout.NORTH);
		JPanel body = column();
		if (loggedOut)
		{
			body.add(text("Log in to see your offers", FontManager.getRunescapeSmallFont(), MUTED));
		}
		else if (next != null)
		{
			JLabel name = text("Next flip: " + next.name, FontManager.getRunescapeFont(), GE_TEXT);
			name.setIcon(icon(next.itemId));
			body.add(name);
			body.add(text("Buy at: " + Gp.full(next.offerBuy) + " gp", FontManager.getRunescapeSmallFont(), Color.WHITE));
			body.add(text("Sell at: " + Gp.full(next.offerSell) + " gp", FontManager.getRunescapeSmallFont(), Color.WHITE));
			body.add(text("Quantity: " + Gp.full(next.maxQty), FontManager.getRunescapeSmallFont(), Color.WHITE));
			body.add(text("Profit: " + Gp.signed(next.potProfit), FontManager.getRunescapeSmallFont(), GOOD));
		}
		c.add(body, BorderLayout.CENTER);
		return c;
	}

	private JPanel filledSlot(OfferTracker.Slot s, long now)
	{
		PriceData data = plugin.prices();
		Market.Deal d = plugin.market(s.itemId);
		GeSlot c = new GeSlot();
		c.add(slotHeader(s.buy ? "Buy" : "Sell"), BorderLayout.NORTH);

		JPanel body = new JPanel(new BorderLayout(8, 0));
		body.setOpaque(false);
		JLabel pic = new JLabel(icon(s.itemId));
		pic.setVerticalAlignment(SwingConstants.TOP);
		body.add(pic, BorderLayout.WEST);
		JPanel info = column();
		info.add(text(data.name(s.itemId), FontManager.getRunescapeBoldFont(), Color.WHITE));
		info.add(text(Gp.full(s.filled) + " / " + Gp.full(s.total) + " at " + Gp.full(s.price), FontManager.getRunescapeSmallFont(), Color.WHITE));
		if (s.isDone())
		{
			info.add(text(s.isCancelled() ? "Cancelled, collect it" : (s.buy ? "Bought" : "Sold") + ", collect it",
				FontManager.getRunescapeSmallFont(), GOOD));
		}
		else
		{
			long idle = now - s.lastActivity;
			boolean stale = idle > plugin.staleMinutes() * 60_000L;
			info.add(text(Gp.duration(idle) + " since last fill" + (stale ? " (stale)" : ""), FontManager.getRunescapeSmallFont(), stale ? WARN : MUTED));
		}
		Advice.Tip tip = MerchPanel.advice(plugin, s, d, now);
		if (tip != null)
		{
			JLabel t = text("<html><div style='width:150px'>" + tip.text + "</div></html>", FontManager.getRunescapeSmallFont(),
				tip.urgent ? BAD : WARN);
			info.add(t);
		}
		if (s.buy && d != null)
		{
			long each = GeTax.afterTax(s.itemId, d.offerSell) - s.price;
			info.add(text("Flip now: " + Gp.signed(each * s.total), FontManager.getRunescapeSmallFont(), colorOf(each)));
		}
		body.add(info, BorderLayout.CENTER);
		c.add(body, BorderLayout.CENTER);

		Color bar = s.isCancelled() ? BAR_CANCELLED : s.isDone() ? BAR_DONE : BAR_FILLING;
		c.add(new GeBar(s.total == 0 ? 0 : (double) s.filled / s.total, bar), BorderLayout.SOUTH);
		return c;
	}

