	/** A GE slot: raised brown box. */
	private static final class GeSlot extends JPanel
	{
		GeSlot()
		{
			super(new BorderLayout(0, 6));
			setOpaque(false);
			setBorder(new EmptyBorder(6, 8, 8, 8));
			setPreferredSize(new Dimension(220, 130));
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			int w = getWidth();
			int h = getHeight();
			g.setColor(GE_SLOT);
			g.fillRect(0, 0, w, h);
			g.setColor(GE_LIGHT);
			g.drawLine(0, 0, w - 1, 0);
			g.drawLine(0, 0, 0, h - 1);
			g.setColor(GE_DARK);
			g.drawLine(w - 1, 0, w - 1, h - 1);
			g.drawLine(0, h - 1, w - 1, h - 1);
		}
	}

	/** The GE's progress bar: orange while filling, green when done, red when cancelled. */
	private static final class GeBar extends JComponent
	{
		private final double fraction;
		private final Color color;

		GeBar(double fraction, Color color)
		{
			this.fraction = Math.max(0, Math.min(1, fraction));
			this.color = color;
			setPreferredSize(new Dimension(10, 12));
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			g.setColor(BAR_BG);
			g.fillRect(0, 0, getWidth(), getHeight());
			g.setColor(color);
			g.fillRect(1, 1, (int) Math.round((getWidth() - 2) * fraction), getHeight() - 2);
		}
	}

