		table.setGridColor(ColorScheme.DARK_GRAY_COLOR);
		table.setSelectionBackground(ColorScheme.MEDIUM_GRAY_COLOR);
		table.setSelectionForeground(Color.WHITE);
		table.setFillsViewportHeight(true);
		table.setToolTipText("Click a column title to sort by it, click again to flip. Click a row for its price chart.");
		JTableHeader header = table.getTableHeader();
		header.setFont(FontManager.getRunescapeBoldFont());
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		header.setForeground(ORANGE);
		header.setReorderingAllowed(false);

		TableRowSorter<DealsModel> sorter = new TableRowSorter<DealsModel>(model)
		{
			@Override
			public void toggleSortOrder(int column)
			{
				// Biggest first on the first click (A to Z for names); a second click flips it.
				if (!isSortable(column))
				{
					return;
				}
				List<? extends RowSorter.SortKey> keys = getSortKeys();
				SortOrder order = column == DealsModel.NAME ? SortOrder.ASCENDING : SortOrder.DESCENDING;
				if (!keys.isEmpty() && keys.get(0).getColumn() == column)
				{
					order = keys.get(0).getSortOrder() == SortOrder.DESCENDING ? SortOrder.ASCENDING : SortOrder.DESCENDING;
				}
				setSortKeys(Collections.singletonList(new RowSorter.SortKey(column, order)));
			}
		};
		sorter.setSortable(DealsModel.ICON, false);
		sorter.setSortKeys(Collections.singletonList(new RowSorter.SortKey(DealsModel.POTENTIAL, SortOrder.DESCENDING)));
		table.setRowSorter(sorter);

		table.setDefaultRenderer(Object.class, new Cells());
		table.setDefaultRenderer(Long.class, new Cells());
		table.setDefaultRenderer(Double.class, new Cells());
		table.setDefaultRenderer(Integer.class, new Cells());
		int[] widths = {44, 230, 100, 100, 80, 100, 70, 90, 90, 80, 120, 60};
		for (int i = 0; i < widths.length; i++)
		{
			table.getColumnModel().getColumn(i).setPreferredWidth(widths[i]);
		}
		table.getColumnModel().getColumn(DealsModel.ICON).setMaxWidth(48);

		// Selecting a row (click or arrow keys) opens its chart.
		table.getSelectionModel().addListSelectionListener(e -> {
			int row = table.getSelectedRow();
			if (e.getValueIsAdjusting() || row < 0)
			{
				return;
			}
			int id = model.rows.get(table.convertRowIndexToModel(row)).itemId;
			if (id != chartItem)
			{
				showChart(id);
			}
		});

		tableScroll = new JScrollPane(table);
		tableScroll.setBorder(BorderFactory.createLineBorder(ColorScheme.DARKER_GRAY_COLOR));
		tableScroll.getViewport().setBackground(ColorScheme.DARKER_GRAY_COLOR);
		tableScroll.getVerticalScrollBar().setUnitIncrement(36);

		buildChartPanel();
		split.setBorder(null);
		split.setOpaque(false);
		split.setResizeWeight(0.5);
		split.setContinuousLayout(true);
		dealsHolder.setOpaque(false);
		dealsHolder.add(tableScroll, BorderLayout.CENTER);
		p.add(dealsHolder, BorderLayout.CENTER);
		return p;
	}

