	private void buildChartPanel()
	{
		chartPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		chartPanel.setBorder(new EmptyBorder(8, 10, 8, 10));
		chartPanel.setMinimumSize(new Dimension(300, 200));

		JPanel head = new JPanel(new BorderLayout(12, 0));
		head.setOpaque(false);
		JPanel info = new JPanel();
		info.setLayout(new BoxLayout(info, BoxLayout.Y_AXIS));
		info.setOpaque(false);
		chartName.setFont(FontManager.getRunescapeBoldFont().deriveFont(18f));
		chartName.setForeground(Color.WHITE);
		chartNow.setFont(FontManager.getRunescapeFont());
		chartNow.setForeground(MUTED);
		info.add(chartName);
		info.add(chartNow);
		head.add(info, BorderLayout.CENTER);

		JPanel buttons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
		buttons.setOpaque(false);
		for (int i = 0; i < CHART_STEPS.length; i++)
		{
			String step = CHART_STEPS[i][0];
			JButton b = chartButton(CHART_STEPS[i][1]);
			b.addActionListener(e -> {
				chartStep = step;
				loadChart();
			});
			stepButtons[i] = b;
			buttons.add(b);
		}
		buttons.add(Box.createHorizontalStrut(10));
		JButton wiki = chartButton("OSRS Wiki");
		wiki.setToolTipText("Open this item's price page in your browser");
		wiki.addActionListener(e -> LinkBrowser.browse("https://prices.runescape.wiki/osrs/item/" + chartItem));
		buttons.add(wiki);
		JButton close = chartButton("Close");
		close.addActionListener(e -> hideChart());
		buttons.add(close);
		head.add(buttons, BorderLayout.EAST);
		chartPanel.add(head, BorderLayout.NORTH);

		chart.setDetailed();
		chartPanel.add(chart, BorderLayout.CENTER);
	}

	private static JButton chartButton(String text)
	{
		JButton b = new JButton(text);
		b.setFont(FontManager.getRunescapeSmallFont());
		b.setFocusPainted(false);
		return b;
	}

	private void showChart(int itemId)
	{
		boolean wasOpen = chartItem > 0;
		chartItem = itemId;
		if (!wasOpen)
		{
			dealsHolder.removeAll();
			split.setTopComponent(tableScroll);
			split.setBottomComponent(chartPanel);
			dealsHolder.add(split, BorderLayout.CENTER);
			dealsHolder.revalidate();
			dealsHolder.repaint();
			SwingUtilities.invokeLater(() -> split.setDividerLocation(0.45));
		}
		loadChart();
	}

	private void hideChart()
	{
		chartItem = -1;
		chartToken++;
		split.setTopComponent(null);
		split.setBottomComponent(null);
		dealsHolder.removeAll();
		dealsHolder.add(tableScroll, BorderLayout.CENTER);
		dealsHolder.revalidate();
		dealsHolder.repaint();
		table.clearSelection();
	}

	private void loadChart()
	{
		int token = ++chartToken;
		chart.setMessage("Loading…");
		updateChartHeader();
		plugin.history(chartItem, chartStep).whenComplete((points, e) -> SwingUtilities.invokeLater(() -> {
			if (token != chartToken)
			{
				return;
			}
			if (e != null || points == null)
			{
				chart.setMessage("Couldn't load the price history");
				return;
			}
			int n = points.size();
			long[] x = new long[n];
			long[] hi = new long[n];
			long[] lo = new long[n];
			long[] traded = new long[n];
			for (int i = 0; i < n; i++)
			{
				PriceData.Point pt = points.get(i);
				x[i] = pt.timestamp * 1000;
				hi[i] = pt.avgHighPrice == null ? LineChart.NONE : pt.avgHighPrice;
				lo[i] = pt.avgLowPrice == null ? LineChart.NONE : pt.avgLowPrice;
				traded[i] = pt.highPriceVolume + pt.lowPriceVolume;
			}
			chart.setSeries(Arrays.asList(
				new LineChart.Series(x, hi, GOOD, "Sell price (insta-buy)"),
				new LineChart.Series(x, lo, ORANGE, "Buy price (insta-sell)")), false);
			chart.setVolume(x, traded);
		}));
	}

	/** Item name and today's numbers above the chart, and which time range is picked. */
	private void updateChartHeader()
	{
		if (chartItem <= 0)
		{
			return;
		}
		chartName.setText(plugin.prices().name(chartItem));
		chartName.setIcon(icon(chartItem));
		Market.Deal d = plugin.market(chartItem);
		chartNow.setText(d == null ? "No live price right now"
			: "Now: buy at " + Gp.full(d.buy) + "  ·  sell at " + Gp.full(d.sell) + "  ·  " + Gp.signed(d.margin)
				+ " ea after tax  ·  " + Gp.shortForm(d.volHr) + " trades/hr");
		for (int i = 0; i < CHART_STEPS.length; i++)
		{
			stepButtons[i].setForeground(CHART_STEPS[i][0].equals(chartStep) ? ORANGE : Color.WHITE);
		}
	}

	/** Keeps the charted item highlighted after the table refreshes. */
	private void reselectChartItem()
	{
		if (chartItem <= 0)
		{
			return;
		}
		for (int i = 0; i < model.rows.size(); i++)
		{
			if (model.rows.get(i).itemId == chartItem)
			{
				int v = table.convertRowIndexToView(i);
				if (v >= 0)
				{
					table.setRowSelectionInterval(v, v);
				}
				return;
			}
		}
	}

	private void rebuildDeals()
	{
		PriceData data = plugin.prices();
		String q = search.getText().trim().toLowerCase(Locale.US);
		List<Market.Deal> rows = new ArrayList<>();
		if (q.isEmpty())
		{
			rows.addAll(plugin.deals());
			count.setText(data.isEmpty() ? plugin.priceStatus() : rows.size() + " deals pass your filters");
		}
		else
		{
			// Searching shows any item, ignoring the deal filters, so you can always look one up.
			for (Map.Entry<Integer, PriceData.Item> e : data.items.entrySet())
			{
				if (e.getValue().name.toLowerCase(Locale.US).contains(q))
				{
					Market.Deal d = plugin.market(e.getKey());
					if (d != null)
					{
						rows.add(d);
					}
				}
				if (rows.size() >= SEARCH_LIMIT)
				{
					break;
				}
			}
			count.setText(rows.size() + " items match");
		}
		model.set(rows);
		reselectChartItem();
	}

	private static final class DealsModel extends AbstractTableModel
	{
		static final int ICON = 0;
		static final int NAME = 1;
		static final int POTENTIAL = 10;
		private static final String[] NAMES = {"", "Item", "Buy at", "Sell at", "Tax", "Profit ea", "ROI", "Vol / hr",
			"Limit left", "Max qty", "Potential", "Age"};
		private static final Class<?>[] TYPES = {Integer.class, String.class, Long.class, Long.class, Long.class, Long.class,
			Double.class, Long.class, Long.class, Long.class, Long.class, Long.class};

		List<Market.Deal> rows = new ArrayList<>();

		void set(List<Market.Deal> rows)
		{
			this.rows = rows;
			fireTableDataChanged();
		}

		@Override
		public int getRowCount()
		{
			return rows.size();
		}

		@Override
		public int getColumnCount()
		{
			return NAMES.length;
		}

		@Override
		public String getColumnName(int c)
		{
			return NAMES[c];
		}

		@Override
		public Class<?> getColumnClass(int c)
		{
			return TYPES[c];
		}

		@Override
		public Object getValueAt(int r, int c)
		{
			Market.Deal d = rows.get(r);
			switch (c)
			{
				case 0:
					return d.itemId;
				case 1:
					return d.name;
				case 2:
					return d.offerBuy;
				case 3:
					return d.offerSell;
				case 4:
					return d.tax;
				case 5:
					return d.margin;
				case 6:
					return d.roi;
				case 7:
					return d.volHr;
				case 8:
					return d.limit == null ? -1L : (long) d.limitLeft;
				case 9:
					return d.maxQty;
				case 10:
					return d.potProfit;
				default:
					return Math.max(0, System.currentTimeMillis() / 1000 - d.oldest);
			}
		}
	}

	private final class Cells extends DefaultTableCellRenderer
	{
		@Override
		public Component getTableCellRendererComponent(JTable t, Object value, boolean selected, boolean focus, int row, int col)
		{
			super.getTableCellRendererComponent(t, value, selected, false, row, col);
			int c = t.convertColumnIndexToModel(col);
			Market.Deal d = model.rows.get(t.convertRowIndexToModel(row));
			setIcon(null);
			setHorizontalAlignment(SwingConstants.RIGHT);
			setForeground(Color.WHITE);
			setBorder(new EmptyBorder(0, 6, 0, 8));
			switch (c)
			{
				case DealsModel.ICON:
					setText("");
					setIcon(icon(d.itemId));
					setHorizontalAlignment(SwingConstants.CENTER);
					break;
				case DealsModel.NAME:
					setText(d.name + (d.spike ? "  (spike)" : ""));
					setForeground(d.spike ? WARN : ORANGE);
					setHorizontalAlignment(SwingConstants.LEFT);
					break;
				case 5:
				case 10:
					long v = (Long) value;
					setText((v > 0 ? "+" : "") + Gp.full(v));
					setForeground(colorOf(v));
					break;
				case 6:
					setText(String.format(Locale.US, "%.2f%%", (Double) value));
					break;
				case 8:
					setText((Long) value < 0 ? "?" : Gp.full((Long) value));
					break;
				case 11:
					long s = (Long) value;
					setText(s < 60 ? s + "s" : (s / 60) + "m");
					setForeground(MUTED);
					break;
				default:
					setText(Gp.full((Long) value));
			}
			return this;
		}
	}

	// ---------------------------------------------------------------- helpers

	/** Item picture, cached; repaints once the game has drawn it. */
	private Icon icon(int itemId)
	{
		if (itemManager == null)
		{
			return null;
		}
		return icons.computeIfAbsent(itemId, id -> {
			AsyncBufferedImage img = itemManager.getImage(id);
			ImageIcon icon = new ImageIcon(img);
			img.onLoaded(() -> SwingUtilities.invokeLater(() -> {
				icon.setImage(img);
				table.repaint();
				slots.repaint();
				chartName.repaint();
			}));
			return icon;
		});
	}

	private static JLabel text(String s, Font font, Color color)
	{
		JLabel l = new JLabel(s);
		l.setFont(font);
		l.setForeground(color);
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		return l;
	}

