package com.merchtool.ui;

import com.merchtool.core.Gp;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * A line chart: gold over time. Used small for an item's price history and for profit over time, and big (detailed)
 * in Large mode, with price gridlines, dates along the bottom, volume bars and a readout under the mouse.
 */
final class LineChart extends JPanel
{
	/** Marks a gap: nothing traded in that step. */
	static final long NONE = Long.MIN_VALUE;

	static final class Series
	{
		final long[] x;
		final long[] y;
		final Color color;
		/** Shown in the legend and the hover readout of a detailed chart. */
		final String name;

		Series(long[] x, long[] y, Color color)
		{
			this(x, y, color, null);
		}

		Series(long[] x, long[] y, Color color, String name)
		{
			this.x = x;
			this.y = y;
			this.color = color;
			this.name = name;
		}
	}

	private static final Color GRID = new Color(0x3A3A3A);
	private static final Color TEXT = ColorScheme.LIGHT_GRAY_COLOR.darker();
	private static final Color VOLUME = new Color(0x55606E);
	private static final Color HOVER = new Color(0x9A9A9A);
	private static final Color READOUT = new Color(20, 20, 20, 240);
	private static final DateTimeFormatter HOUR = DateTimeFormatter.ofPattern("EEE HH:mm", Locale.US);
	private static final DateTimeFormatter DAY = DateTimeFormatter.ofPattern("MMM d", Locale.US);
	private static final DateTimeFormatter MONTH = DateTimeFormatter.ofPattern("MMM yyyy", Locale.US);
	private static final DateTimeFormatter WHEN = DateTimeFormatter.ofPattern("EEE MMM d yyyy, HH:mm", Locale.US);

	private final List<Series> series = new ArrayList<>();
	private String message = "";
	/** Draws a line at 0, for profit charts. */
	private boolean zeroLine;
	private boolean detailed;
	/** Trades per step, drawn as bars under a detailed chart. Null for none. */
	private long[] volX;
	private long[] vol;
	/** Mouse x over a detailed chart, or -1. */
	private int hoverX = -1;

	LineChart(int height)
	{
		setOpaque(true);
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setPreferredSize(new Dimension(100, height));
		setMinimumSize(new Dimension(50, height));
		setAlignmentX(LEFT_ALIGNMENT);
	}

	/** Switches to the big chart: gridlines, dates, volume bars and a readout that follows the mouse. */
	void setDetailed()
	{
		detailed = true;
		setMinimumSize(new Dimension(200, 140));
		MouseAdapter hover = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				hoverX = e.getX();
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hoverX = -1;
				repaint();
			}
		};
		addMouseListener(hover);
		addMouseMotionListener(hover);
	}

	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}

	void setSeries(List<Series> s, boolean zeroLine)
	{
		series.clear();
		series.addAll(s);
		this.zeroLine = zeroLine;
		message = "";
		repaint();
	}

	/** Volume bars for a detailed chart, one per x. */
	void setVolume(long[] x, long[] v)
	{
		volX = x;
		vol = v;
		repaint();
	}

	/** Shows text instead of lines, e.g. "Loading…". */
	void setMessage(String text)
	{
		series.clear();
		volX = null;
		vol = null;
		message = text;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics g0)
	{
		super.paintComponent(g0);
		Graphics2D g = (Graphics2D) g0.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setFont(detailed ? FontManager.getRunescapeFont() : FontManager.getRunescapeSmallFont());
		FontMetrics fm = g.getFontMetrics();
		int w = getWidth();
		int h = getHeight();

		long minX = Long.MAX_VALUE;
		long maxX = Long.MIN_VALUE;
		long minY = Long.MAX_VALUE;
		long maxY = Long.MIN_VALUE;
		for (Series s : series)
		{
			for (int i = 0; i < s.x.length; i++)
			{
				if (s.y[i] == NONE)
				{
					continue;
				}
				minX = Math.min(minX, s.x[i]);
				maxX = Math.max(maxX, s.x[i]);
				minY = Math.min(minY, s.y[i]);
				maxY = Math.max(maxY, s.y[i]);
			}
		}
		if (minX == Long.MAX_VALUE)
		{
			g.setColor(TEXT);
			String m = message.isEmpty() ? "No data" : message;
			g.drawString(m, (w - fm.stringWidth(m)) / 2, h / 2 + fm.getAscent() / 2);
			g.dispose();
			return;
		}
		if (zeroLine)
		{
			minY = Math.min(minY, 0);
			maxY = Math.max(maxY, 0);
		}
		if (maxY == minY)
		{
			maxY++;
			minY--;
		}
		if (maxX == minX)
		{
			maxX++;
		}
		if (detailed)
		{
			paintDetailed(g, fm, w, h, minX, maxX, minY, maxY);
		}
		else
		{
			paintSmall(g, fm, w, h, minX, maxX, minY, maxY);
		}
		g.dispose();
	}

	private void paintSmall(Graphics2D g, FontMetrics fm, int w, int h, long minX, long maxX, long minY, long maxY)
	{
		String top = Gp.shortForm(maxY);
		String bottom = Gp.shortForm(minY);
		int left = Math.max(fm.stringWidth(top), fm.stringWidth(bottom)) + 6;
		int pad = 4;
		int plotTop = pad + fm.getAscent() / 2;
		int plotBottom = h - pad - fm.getHeight();
		int plotW = Math.max(1, w - left - pad);
		int plotH = Math.max(1, plotBottom - plotTop);

		g.setColor(GRID);
		g.drawLine(left, plotTop, left + plotW, plotTop);
		g.drawLine(left, plotBottom, left + plotW, plotBottom);
		g.setColor(TEXT);
		g.drawString(top, 2, plotTop + fm.getAscent() / 2);
		g.drawString(bottom, 2, plotBottom + fm.getAscent() / 2);
		if (zeroLine && minY < 0 && maxY > 0)
		{
			int zy = plotBottom - (int) ((double) (0 - minY) / (maxY - minY) * plotH);
			g.setColor(GRID);
			g.drawLine(left, zy, left + plotW, zy);
		}
		String from = ago(minX);
		g.setColor(TEXT);
		g.drawString(from, left, h - pad);
		g.drawString("now", left + plotW - fm.stringWidth("now"), h - pad);
		drawLines(g, left, plotW, plotBottom, plotH, minX, maxX, minY, maxY);
	}

	private void paintDetailed(Graphics2D g, FontMetrics fm, int w, int h, long minX, long maxX, long minY, long maxY)
	{
		// A little headroom so the lines don't run along the edges.
		long extra = Math.max(1, (maxY - minY) / 12);
		minY = Math.max(0, minY - extra);
		maxY += extra;

		int ticks = 5;
		long[] yTicks = new long[ticks];
		int labelW = 0;
		for (int i = 0; i < ticks; i++)
		{
			yTicks[i] = minY + (maxY - minY) * i / (ticks - 1);
			labelW = Math.max(labelW, fm.stringWidth(Gp.full(yTicks[i])));
		}
		int pad = 8;
		int left = labelW + 14;
		int plotW = Math.max(1, w - left - pad - 4);
		int plotTop = pad + fm.getHeight() + 6;
		int axisH = fm.getHeight() + 6;
		boolean hasVolume = vol != null && volX != null && vol.length == volX.length;
		int volH = hasVolume ? Math.max(24, (h - plotTop - axisH - pad) / 5) : 0;
		int volBottom = h - pad - axisH;
		int plotBottom = hasVolume ? volBottom - volH - fm.getHeight() - 4 : volBottom;
		int plotH = Math.max(1, plotBottom - plotTop);

		// Price gridlines and labels.
		for (long v : yTicks)
		{
			int y = plotBottom - (int) ((double) (v - minY) / (maxY - minY) * plotH);
			g.setColor(GRID);
			g.drawLine(left, y, left + plotW, y);
			g.setColor(TEXT);
			String s = Gp.full(v);
			g.drawString(s, left - 8 - fm.stringWidth(s), y + fm.getAscent() / 2 - 1);
		}

		// Time labels along the bottom.
		long span = maxX - minX;
		DateTimeFormatter f = span <= 3 * 86_400_000L ? HOUR : span <= 200 * 86_400_000L ? DAY : MONTH;
		int xTicks = Math.max(2, Math.min(8, plotW / 120));
		for (int i = 0; i < xTicks; i++)
		{
			long t = minX + span * i / (xTicks - 1);
			int x = left + (int) ((double) (t - minX) / span * plotW);
			g.setColor(GRID);
			g.drawLine(x, plotTop, x, plotBottom);
			String s = f.format(Instant.ofEpochMilli(t).atZone(ZoneId.systemDefault()));
			int sx = Math.max(left, Math.min(left + plotW - fm.stringWidth(s), x - fm.stringWidth(s) / 2));
			g.setColor(TEXT);
			g.drawString(s, sx, h - pad);
		}

		// Volume bars.
		if (hasVolume)
		{
			long maxVol = 1;
			for (long v : vol)
			{
				maxVol = Math.max(maxVol, v);
			}
			int bw = Math.max(1, plotW / Math.max(1, vol.length) - 1);
			g.setColor(VOLUME);
			for (int i = 0; i < vol.length; i++)
			{
				if (vol[i] <= 0 || volX[i] < minX || volX[i] > maxX)
				{
					continue;
				}
				int x = left + (int) ((double) (volX[i] - minX) / span * plotW);
				int bh = Math.max(1, (int) ((double) vol[i] / maxVol * volH));
				g.fillRect(x - bw / 2, volBottom - bh, bw, bh);
			}
			g.setColor(GRID);
			g.drawLine(left, volBottom, left + plotW, volBottom);
			g.setColor(TEXT);
			String top = Gp.shortForm(maxVol);
			g.drawString(top, left - 8 - fm.stringWidth(top), volBottom - volH + fm.getAscent() / 2);
			g.drawString("Vol", left - 8 - fm.stringWidth("Vol"), volBottom);
		}

		g.setStroke(new BasicStroke(2f));
		drawLines(g, left, plotW, plotBottom, plotH, minX, maxX, minY, maxY);

		// Legend.
		int lx = left;
		for (Series s : series)
		{
			if (s.name == null)
			{
				continue;
			}
			g.setColor(s.color);
			g.fillRect(lx, pad + fm.getAscent() / 2 - 3, 10, 6);
			g.setColor(Color.WHITE);
			g.drawString(s.name, lx + 14, pad + fm.getAscent());
			lx += 14 + fm.stringWidth(s.name) + 20;
		}

		if (hoverX >= left && hoverX <= left + plotW && !series.isEmpty())
		{
			paintReadout(g, fm, left, plotW, plotTop, plotBottom, plotH, volBottom, minX, maxX, minY, maxY);
		}
	}

	/** Vertical line at the step nearest the mouse, a dot on each line, and a box with that step's numbers. */
	private void paintReadout(Graphics2D g, FontMetrics fm, int left, int plotW, int plotTop, int plotBottom, int plotH,
		int volBottom, long minX, long maxX, long minY, long maxY)
	{
		long[] xs = series.get(0).x;
		if (xs.length == 0)
		{
			return;
		}
		long t = minX + (long) ((double) (hoverX - left) / plotW * (maxX - minX));
		int best = 0;
		for (int i = 1; i < xs.length; i++)
		{
			if (Math.abs(xs[i] - t) < Math.abs(xs[best] - t))
			{
				best = i;
			}
		}
		int x = left + (int) ((double) (xs[best] - minX) / (maxX - minX) * plotW);
		g.setStroke(new BasicStroke(1f));
		g.setColor(HOVER);
		g.drawLine(x, plotTop, x, volBottom);

		List<String> lines = new ArrayList<>();
		List<Color> colors = new ArrayList<>();
		lines.add(WHEN.format(Instant.ofEpochMilli(xs[best]).atZone(ZoneId.systemDefault())));
		colors.add(Color.WHITE);
		for (Series s : series)
		{
			if (best >= s.y.length)
			{
				continue;
			}
			long v = s.y[best];
			if (v != NONE)
			{
				int y = plotBottom - (int) ((double) (v - minY) / (maxY - minY) * plotH);
				g.setColor(s.color);
				g.fillOval(x - 4, y - 4, 8, 8);
			}
			lines.add((s.name == null ? "" : s.name + ": ") + (v == NONE ? "no trades" : Gp.full(v)));
			colors.add(s.color);
		}
		if (vol != null && best < vol.length)
		{
			lines.add("Traded: " + Gp.full(vol[best]));
			colors.add(TEXT);
		}

		int bw = 0;
		for (String s : lines)
		{
			bw = Math.max(bw, fm.stringWidth(s));
		}
		bw += 16;
		int bh = lines.size() * fm.getHeight() + 10;
		int bx = x + 12 + bw <= left + plotW ? x + 12 : x - 12 - bw;
		int by = plotTop + 6;
		g.setColor(READOUT);
		g.fillRoundRect(bx, by, bw, bh, 6, 6);
		g.setColor(GRID);
		g.drawRoundRect(bx, by, bw, bh, 6, 6);
		for (int i = 0; i < lines.size(); i++)
		{
			g.setColor(colors.get(i));
			g.drawString(lines.get(i), bx + 8, by + 5 + fm.getAscent() + i * fm.getHeight());
		}
	}

	private void drawLines(Graphics2D g, int left, int plotW, int plotBottom, int plotH, long minX, long maxX, long minY, long maxY)
	{
		if (!detailed)
		{
			g.setStroke(new BasicStroke(1.5f));
		}
		for (Series s : series)
		{
			g.setColor(s.color);
			int px = -1;
			int py = -1;
			for (int i = 0; i < s.x.length; i++)
			{
				if (s.y[i] == NONE)
				{
					continue;
				}
				int x = left + (int) ((double) (s.x[i] - minX) / (maxX - minX) * plotW);
				int y = plotBottom - (int) ((double) (s.y[i] - minY) / (maxY - minY) * plotH);
				if (px >= 0)
				{
					g.drawLine(px, py, x, y);
				}
				else
				{
					g.fillRect(x - 1, y - 1, 2, 2);
				}
				px = x;
				py = y;
			}
		}
	}

	/** "30h ago" style label for the left edge. x is epoch millis. */
	private static String ago(long millis)
	{
		long h = Math.max(0, (System.currentTimeMillis() - millis) / 3600_000L);
		if (h < 1)
		{
			return "<1h ago";
		}
		return h < 72 ? h + "h ago" : (h / 24) + "d ago";
	}
}

