/** What the panel needs from the plugin. Lets the panel be rendered and tested without a game client. */
public interface MerchModel
{
	String priceStatus();

	/** Null when logged out. */
	Ledger ledger();

	/** Null when logged out. */
	OfferTracker.Slot[] slots();

	long escrow();

	Object lock();

	PriceData prices();

	List<Market.Deal> deals();

	Market.Deal market(int itemId);

	void setBankroll(long gold);

	/** Wipes flips, profit totals and the bankroll for this account. Held items, buy limits and stars stay. */
	void resetStats();

	void forgetHeld(int itemId);

	/** Minutes without a fill before a slot counts as stale. */
	int staleMinutes();

	/** How many empty slots get a Next flip: 1, or one per empty slot when splitting gold across slots. */
	int suggestions();

	/** Item on the GE buy/sell screen right now, or -1 when that screen isn't open. */
	int geItem();

	/** True when the GE screen is setting up a sell offer. */
	boolean geSell();

	/** Alch, decant or set flips, best first. Empty when logged out or prices haven't loaded. */
	List<Recipes.Result> recipes(Recipes.Kind kind);

	/** Starred items for this account (a copy). Empty when logged out. */
	Set<Integer> starred();

	void toggleStar(int itemId);

	/** Price history for the chart. Completes off the Swing thread. */
	CompletableFuture<List<PriceData.Point>> history(int itemId, String step);

	/** Epoch millis this account logged in, or 0 when logged out. */
	long sessionStart();
}

