	// ---------------------------------------------------------------- tiles

	private void rebuildTiles()
	{
		tiles.removeAll();
		Ledger l = plugin.ledger();
		if (l == null)
		{
			tiles.add(tile("Bankroll", "—", "log in", null));
			tiles.add(tile("Free to spend", "—", "", null));
			tiles.add(tile("In the GE", "—", "", null));
			tiles.add(tile("Held items", "—", "", null));
			tiles.add(tile("Today", "—", "", null));
			tiles.add(tile("All time", "—", "", null));
			return;
		}
		long escrow = plugin.escrow();
		long now = System.currentTimeMillis();
		long today = startOfToday();
		long todayP;
		long allP;
		long held;
		long heldQty = 0;
		int flipsToday = 0;
		int wins = 0;
		int losses = 0;
		synchronized (plugin.lock())
		{
			todayP = l.profitSince(today);
			allP = l.profitSince(0);
			held = l.heldCost();
			for (Ledger.Lot lot : l.lots)
			{
				heldQty += lot.qty;
			}
			for (Ledger.Flip f : l.flips)
			{
				if (f.time >= today)
				{
					flipsToday++;
				}
			}
			wins = l.wins();
			losses = l.losses();
		}
		if (l.hasBankroll())
		{
			long free = l.freeGold(escrow);
			// Small profits vanish in "10.0M", so the line under it shows the change in full.
			long change = l.bankroll() - l.bankrollStart;
			tiles.add(tile("Bankroll", Gp.shortForm(l.bankroll()),
				change == 0 ? "started " + Gp.shortForm(l.bankrollStart) : (change > 0 ? "+" : "") + Gp.full(change) + " since set",
				null));
			tiles.add(tile("Free to spend", Gp.shortForm(free), "sizes the deals", free < 0 ? BAD : GOOD));
		}
		else
		{
			tiles.add(tile("Bankroll", "Not set", "Stats tab", WARN));
			tiles.add(tile("Free to spend", "—", "set bankroll", null));
		}
		tiles.add(tile("In offers", Gp.shortForm(escrow), "unfilled buys", null));
		tiles.add(tile("Held items", Gp.shortForm(held), Gp.full(heldQty) + " items, paid", null));
		tiles.add(tile("Today", Gp.signed(todayP), flipsToday + " flips", colorOf(todayP)));
		tiles.add(tile("All time", Gp.signed(allP), wins + " won · " + losses + " lost", colorOf(allP)));
		tiles.revalidate();
	}

	private JPanel tile(String label, String value, String sub, Color valueColor)
	{
		JPanel t = column();
		t.setBackground(CARD);
		t.setOpaque(true);
		t.setBorder(new EmptyBorder(3, 5, 3, 5));
		t.add(small(label.toUpperCase(Locale.US), MUTED));
		JLabel v = new JLabel(value);
		v.setFont(FontManager.getRunescapeBoldFont());
		v.setForeground(valueColor != null ? valueColor : Color.WHITE);
		t.add(left(v));
		if (!sub.isEmpty())
		{
			t.add(small(sub, MUTED));
		}
		return t;
	}

	// ---------------------------------------------------------------- GE screen helper

	/** Prices for the item on the GE buy/sell screen. Shown in the panel only: nothing is typed or drawn in game. */
	private void rebuildGeCard()
	{
		fillGeCard(geCard, plugin, itemManager);
	}

	/** Shared with Large mode. */
	static void fillGeCard(JPanel geCard, MerchModel plugin, ItemManager itemManager)
	{
		geCard.removeAll();
		int id = plugin.geItem();
		Market.Deal d = id > 0 ? plugin.market(id) : null;
		if (d == null)
		{
			geCard.setVisible(false);
			return;
		}
		boolean sell = plugin.geSell();
		JPanel c = card();
		c.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createMatteBorder(0, 3, 0, 0, sell ? GOOD : ORANGE),
			new EmptyBorder(5, 6, 5, 6)));
		c.add(small(sell ? "SELLING IN THE GE" : "BUYING IN THE GE", sell ? GOOD : ORANGE));
		JLabel name = new JLabel(d.name);
		name.setFont(FontManager.getRunescapeBoldFont());
		name.setForeground(Color.WHITE);
		addIcon(itemManager, name, id);
		c.add(left(name));
		if (sell)
		{
			c.add(wrap("List at <b>" + Gp.full(d.offerSell) + "</b>", Color.WHITE));
			c.add(wrap(Gp.full(GeTax.afterTax(id, d.offerSell)) + " each after tax", MUTED));
			Ledger l = plugin.ledger();
			long cost = l == null ? 0 : l.heldAvgCost(id);
			if (cost > 0)
			{
				long each = GeTax.afterTax(id, d.offerSell) - cost;
				c.add(wrap("You paid " + Gp.full(cost) + " each, so " + Gp.signed(each) + " each", colorOf(each)));
			}
		}
		else
		{
			c.add(wrap("Offer <b>" + Gp.full(d.offerBuy) + "</b>", Color.WHITE));
			c.add(wrap("Sell later at " + Gp.full(d.offerSell), Color.WHITE));
			c.add(wrap(Gp.signed(d.margin) + " each after tax", colorOf(d.margin)));
			c.add(wrap("Qty " + Gp.full(d.maxQty) + " makes " + Gp.signed(d.potProfit), colorOf(d.potProfit)));
		}
		c.add(Box.createVerticalStrut(3));
		c.add(wrap("Market now: buy " + Gp.full(d.buy) + ", sell " + Gp.full(d.sell) + " (" + ageText(d) + ")", MUTED));
		c.add(wrap("Limit " + (d.limit == null ? "?" : Gp.full(d.limitLeft) + " left of " + Gp.full(d.limit))
			+ " · " + Gp.shortForm(d.volHr) + " trades/hr", MUTED));
		geCard.add(c);
		geCard.add(Box.createVerticalStrut(6));
		geCard.setVisible(true);
	}

	// ---------------------------------------------------------------- slots

	private void rebuildSlots()
	{
		slotsView.removeAll();
		OfferTracker.Slot[] slots = plugin.slots();
		if (slots == null)
		{
			slotsView.add(note("Log in and your GE offers show up here by themselves."));
			slotsView.revalidate();
			return;
		}
		List<Market.Deal> deals = plugin.deals();
		int suggested = 0;
		int wanted = plugin.suggestions();
		long now = System.currentTimeMillis();
		for (int i = 0; i < slots.length; i++)
		{
			OfferTracker.Slot s = slots[i];
			if (s == null)
			{
				JPanel c = card();
				c.add(small("#" + (i + 1) + "  Empty", MUTED));
				if (suggested < wanted && suggested < deals.size())
				{
					Market.Deal d = deals.get(suggested);
					c.add(small("Next flip: " + d.name, ORANGE));
					c.add(small("Buy at " + Gp.full(d.offerBuy) + " · sell at " + Gp.full(d.offerSell), Color.WHITE));
					c.add(small("Qty " + Gp.full(d.maxQty) + " · profit " + Gp.signed(d.potProfit), GOOD));
					suggested++;
				}
				slotsView.add(c);
				slotsView.add(Box.createVerticalStrut(4));
				continue;
			}
			slotsView.add(slotCard(i, s, now));
			slotsView.add(Box.createVerticalStrut(4));
		}
		slotsView.revalidate();
		slotsView.repaint();
	}

	private JPanel slotCard(int i, OfferTracker.Slot s, long now)
	{
		PriceData data = plugin.prices();
		Market.Deal d = plugin.market(s.itemId);
		JPanel c = card();

		JLabel head = new JLabel("#" + (i + 1) + "  " + (s.buy ? "BUY" : "SELL") + "  " + data.name(s.itemId));
		head.setFont(FontManager.getRunescapeSmallFont());
		head.setForeground(s.buy ? ORANGE : GOOD);
		addIcon(head, s.itemId);
		c.add(left(head));

		c.add(small(Gp.full(s.filled) + " / " + Gp.full(s.total) + " at " + Gp.full(s.price), Color.WHITE));
		if (s.isDone())
		{
			c.add(small(s.isCancelled() ? "Cancelled, collect it" : (s.buy ? "Bought" : "Sold") + ", collect it", GOOD));
		}
		else
		{
			long idle = now - s.lastActivity;
			boolean stale = idle > plugin.staleMinutes() * 60_000L;
			c.add(small(Gp.duration(idle) + " since last fill" + (stale ? " (stale)" : ""), stale ? WARN : MUTED));
		}

		JProgressBar bar = new JProgressBar(0, Math.max(1, s.total));
		bar.setValue(s.filled);
		bar.setForeground(s.isDone() ? GOOD : ORANGE);
		bar.setBackground(ColorScheme.DARK_GRAY_COLOR);
		bar.setBorderPainted(false);
		bar.setPreferredSize(new Dimension(10, 5));
		bar.setMaximumSize(new Dimension(Integer.MAX_VALUE, 5));
		c.add(bar);

		if (d != null)
		{
			c.add(small("Now: buy " + Gp.full(d.buy) + " · sell " + Gp.full(d.sell), MUTED));
			Advice.Tip tip = advice(plugin, s, d, now);
			if (tip != null)
			{
				c.add(wrap(tip.text, tip.urgent ? BAD : WARN));
			}
		}
		long remaining = s.total - s.filled;
		if (s.buy && d != null)
		{
			long each = GeTax.afterTax(s.itemId, d.offerSell) - s.price;
			c.add(small("Flip at today's sell: " + Gp.signed(each) + " ea, " + Gp.signed(each * s.total), colorOf(each)));
		}
		else if (!s.buy && !s.isDone())
		{
			Ledger l = plugin.ledger();
			long cost = l == null ? 0 : l.heldAvgCost(s.itemId);
			if (cost > 0)
			{
				long each = GeTax.afterTax(s.itemId, s.price) - cost;
				c.add(small("Left to sell makes " + Gp.signed(each * remaining) + " after tax", colorOf(each)));
			}
		}
		c.setToolTipText("<html>" + data.name(s.itemId) + "<br>Listed at " + Gp.full(s.price) + " gp<br>"
			+ (s.buy ? "Paid" : "Received") + " so far: " + Gp.full(s.spent) + " gp</html>");
		return c;
	}

	/** What to do about a live offer that isn't going well, or null. Shared with Large mode. */
	static Advice.Tip advice(MerchModel plugin, OfferTracker.Slot s, Market.Deal d, long now)
	{
		Ledger l = plugin.ledger();
		long cost = l == null || s.buy ? 0 : l.heldAvgCost(s.itemId);
		return Advice.forSlot(s, d, cost, now, plugin.staleMinutes() * 60_000L);
	}

	// ---------------------------------------------------------------- deals

	private void rebuildDeals()
	{
		dealsList.removeAll();
		PriceData data = plugin.prices();
		if (detailItem > 0)
		{
			dealsList.add(detailCard(data));
			dealsList.add(Box.createVerticalStrut(6));
		}
		if (data.isEmpty())
		{
			dealsList.add(note(plugin.priceStatus()));
			dealsList.revalidate();
			return;
		}
		DealView v = selectedView();
		sortRow.setVisible(v.recipeKind == null);
		Set<Integer> starred = plugin.starred();
		String q = search.getText().trim().toLowerCase(Locale.US);
		if (v.recipeKind != null)
		{
			rebuildRecipes(v, q);
			return;
		}
		List<Market.Deal> shown = new ArrayList<>();
		if (!q.isEmpty() || v == DealView.STARRED)
		{
			// Searching and the starred list show any item, ignoring the deal filters, so you can always look one up.
			for (Map.Entry<Integer, PriceData.Item> e : data.items.entrySet())
			{
				boolean match = q.isEmpty() || e.getValue().name.toLowerCase(Locale.US).contains(q);
				if (match && (v != DealView.STARRED || starred.contains(e.getKey())))
				{
					Market.Deal d = plugin.market(e.getKey());
					if (d != null)
					{
						shown.add(d);
					}
				}
				if (shown.size() >= DEALS_SHOWN)
				{
					break;
				}
			}
			shown.sort(selectedSort().order);
			if (v == DealView.STARRED && shown.isEmpty())
			{
				dealsList.add(note(starred.isEmpty()
					? "No starred items yet. Click the star on any deal or search result to keep it here."
					: "None of your starred items match."));
			}
		}
		else
		{
			List<Market.Deal> all = plugin.deals();
			if (all.isEmpty())
			{
				dealsList.add(note("No flips pass your filters. Loosen them in the plugin settings."));
			}
			else
			{
				dealsList.add(nextFlip(all.get(0)));
				dealsList.add(Box.createVerticalStrut(6));
				dealsList.add(small(Math.min(DEALS_SHOWN, all.size()) + " of " + all.size() + " deals, by " + selectedSort().toString().toLowerCase(Locale.US), MUTED));
				dealsList.add(Box.createVerticalStrut(4));
			}
			List<Market.Deal> sorted = new ArrayList<>(all);
			sorted.sort(selectedSort().order);
			shown = sorted.subList(0, Math.min(DEALS_SHOWN, sorted.size()));
		}
		for (Market.Deal d : shown)
		{
			dealsList.add(dealRow(d, starred.contains(d.itemId)));
			dealsList.add(Box.createVerticalStrut(2));
		}
		dealsList.revalidate();
		dealsList.repaint();
	}

	private void rebuildRecipes(DealView v, String q)
	{
		List<Recipes.Result> all = plugin.recipes(v.recipeKind);
		List<Recipes.Result> shown = new ArrayList<>();
		for (Recipes.Result r : all)
		{
			if (q.isEmpty() || r.name.toLowerCase(Locale.US).contains(q))
			{
				shown.add(r);
			}
		}
		dealsList.add(note(v.explain));
		if (shown.isEmpty())
		{
			dealsList.add(note(plugin.ledger() == null ? "Log in to size these to your gold." : "Nothing profitable right now."));
		}
		else
		{
			dealsList.add(small(Math.min(DEALS_SHOWN, shown.size()) + " of " + shown.size() + ", by potential profit", MUTED));
			dealsList.add(Box.createVerticalStrut(4));
		}
		PriceData data = plugin.prices();
		for (int i = 0; i < shown.size() && i < DEALS_SHOWN; i++)
		{
			dealsList.add(recipeRow(shown.get(i), data));
			dealsList.add(Box.createVerticalStrut(2));
		}
		dealsList.revalidate();
		dealsList.repaint();
	}

