	private void showDetail(int itemId)
	{
		if (itemId != detailItem)
		{
			detailItem = itemId;
			loadHistory();
		}
		rebuildDeals();
		SwingUtilities.invokeLater(() -> dealsList.scrollRectToVisible(new Rectangle(0, 0, 1, 1)));
	}

	private void loadHistory()
	{
		int token = ++detailToken;
		detailPoints = null;
		detailFailed = false;
		plugin.history(detailItem, detailStep).whenComplete((points, e) -> SwingUtilities.invokeLater(() -> {
			if (token != detailToken)
			{
				return;
			}
			detailFailed = e != null;
			detailPoints = e != null || points == null ? Collections.emptyList() : points;
			rebuildDeals();
		}));
	}

