		steps.setOpaque(false);
		steps.setAlignmentX(Component.LEFT_ALIGNMENT);
		String[][] options = {{"5m", "30 hours"}, {"1h", "2 weeks"}, {"6h", "3 months"}};
		for (String[] o : options)
		{
			JButton b = smallButton(o[1]);
			b.setForeground(o[0].equals(detailStep) ? ORANGE : MUTED);
