		}
		else
		{
			int n = detailPoints.size();
			long[] x = new long[n];
			long[] hi = new long[n];
			long[] lo = new long[n];
			for (int i = 0; i < n; i++)
			{
				PriceData.Point p = detailPoints.get(i);
				x[i] = p.timestamp * 1000;
				hi[i] = p.avgHighPrice == null ? LineChart.NONE : p.avgHighPrice;
				lo[i] = p.avgLowPrice == null ? LineChart.NONE : p.avgLowPrice;
