	private static final ImageIcon STAR_ON = star(true);
	private static final ImageIcon STAR_OFF = star(false);

	/** A small star drawn in code, so it doesn't depend on a font having the glyph. */
	private static ImageIcon star(boolean filled)
	{
		int size = 12;
		BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		Polygon p = new Polygon();
		for (int i = 0; i < 10; i++)
		{
			double r = i % 2 == 0 ? size / 2.0 - 0.5 : size / 4.6;
			double a = Math.PI / 5 * i - Math.PI / 2;
			p.addPoint((int) Math.round(size / 2.0 + r * Math.cos(a)), (int) Math.round(size / 2.0 + r * Math.sin(a)));
		}
		if (filled)
		{
			g.setColor(new Color(0xFFD94A));
			g.fillPolygon(p);
		}
		else
		{
			g.setColor(new Color(0x8A8A8A));
			g.drawPolygon(p);
		}
		g.dispose();
		return new ImageIcon(img);
	}

