	/** Time ranges for the Results section. */
	enum StatRange
	{
		SESSION("This session"), TODAY("Today"), WEEK("Last 7 days"), ALL("All time");

		private final String label;

		StatRange(String label)
		{
			this.label = label;
		}

		/** Epoch millis the range starts. */
		long since(MerchModel plugin, long now)
		{
			switch (this)
			{
				case SESSION:
					return plugin.sessionStart() > 0 ? plugin.sessionStart() : now;
				case TODAY:
					return startOfToday();
				case WEEK:
					return now - 7 * 24 * 3600_000L;
				default:
					return 0;
			}
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	/**
	 * The Stats tab's inputs: bankroll box, range picker and copy button. Each view needs its own, since a
	 * component can only sit in one place.
	 */
	static final class StatsControls
	{
		final JPanel bankrollRow;
		final JComboBox<StatRange> range = new JComboBox<>(StatRange.values());
		final JButton copy = new JButton("Copy flips for a spreadsheet");
		final JButton reset = new JButton("Reset stats");

		StatsControls(MerchModel plugin, Runnable onChange)
		{
			reset.setFont(FontManager.getRunescapeSmallFont());
			reset.setAlignmentX(Component.LEFT_ALIGNMENT);
			reset.setToolTipText("Sets profit, flips and the bankroll back to zero");
			reset.addActionListener(e -> {
				int answer = JOptionPane.showConfirmDialog(reset,
					"<html>Set this account's stats back to zero?<br><br>"
						+ "Wipes: every flip, profit in every time range, and the bankroll.<br>"
						+ "Keeps: held items, buy limit timers, stars and settings.<br><br>"
						+ "This can't be undone.</html>",
					"Reset stats", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
				if (answer == JOptionPane.YES_OPTION)
				{
					plugin.resetStats();
				}
			});

			JTextField input = new JTextField();
			JButton set = new JButton("Set");
			set.addActionListener(e -> {
				long v = Gp.parse(input.getText());
				if (v >= 0)
				{
					plugin.setBankroll(v);
					input.setText("");
				}
			});
			input.addActionListener(e -> set.doClick());
			bankrollRow = row();
			bankrollRow.add(input, BorderLayout.CENTER);
			bankrollRow.add(set, BorderLayout.EAST);

			range.setFont(FontManager.getRunescapeSmallFont());
			range.setSelectedItem(StatRange.TODAY);
			range.setMaximumSize(new Dimension(Integer.MAX_VALUE, range.getPreferredSize().height));
			range.setAlignmentX(Component.LEFT_ALIGNMENT);
			range.addActionListener(e -> onChange.run());

			copy.setFont(FontManager.getRunescapeSmallFont());
			copy.setAlignmentX(Component.LEFT_ALIGNMENT);
			copy.setToolTipText("Copies your flips as CSV text. Paste into Excel or Google Sheets.");
			copy.addActionListener(e -> {
				Ledger l = plugin.ledger();
				if (l == null)
				{
					return;
				}
				List<Ledger.Flip> flips;
				synchronized (plugin.lock())
				{
					flips = new ArrayList<>(l.flips);
				}
				String csv = Csv.flips(flips, plugin.prices(), ZoneId.systemDefault());
				Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(csv), null);
				copy.setText("Copied " + flips.size() + " flips");
				Timer t = new Timer(3000, ev -> copy.setText("Copy flips for a spreadsheet"));
				t.setRepeats(false);
				t.start();
			});
		}

		StatRange selected()
		{
			StatRange r = (StatRange) range.getSelectedItem();
			return r == null ? StatRange.TODAY : r;
		}
	}

	/** Bankroll, results by time range, held items, buy limits and recent flips. Shared with Large mode. */
	static void fillStats(JPanel statsView, MerchModel plugin, StatsControls controls)
	{
		statsView.removeAll();
		Ledger l = plugin.ledger();
		if (l == null)
		{
			statsView.add(note("Log in to see your stats."));
			statsView.revalidate();
			return;
		}
		PriceData data = plugin.prices();
		long now = System.currentTimeMillis();

		statsView.add(heading("Gold to merch with"));
		statsView.add(note(l.hasBankroll() ? "Now " + Gp.full(l.bankroll()) + " (started " + Gp.full(l.bankrollStart) + ")"
			: "Type the gold you're flipping with, e.g. 100m"));
		statsView.add(controls.bankrollRow);
		statsView.add(note("Setting it starts the count fresh. Old flips stay in All time."));

		StatRange range = controls.selected();
		long since = range.since(plugin, now);
		List<Ledger.Lot> lots;
		List<Ledger.Flip> flips;
		List<Map.Entry<Integer, Ledger.Window>> limits = new ArrayList<>();
		long untracked;
		Ledger.Summary sum;
		synchronized (plugin.lock())
		{
			lots = new ArrayList<>(l.lots);
			flips = new ArrayList<>(l.flips);
			for (Map.Entry<Integer, Ledger.Window> e : l.limits.entrySet())
			{
				if (now - e.getValue().start < Ledger.LIMIT_WINDOW_MS)
				{
					limits.add(e);
				}
			}
			untracked = l.untrackedSold;
			sum = l.summary(since);
		}

		statsView.add(heading("Results"));
		statsView.add(controls.range);
		statsView.add(Box.createVerticalStrut(4));
		long start = range == StatRange.SESSION ? since : sum.firstBuy;
		long perHour = sum.perHour(start, now);
		JPanel grid = new JPanel(new GridLayout(2, 2, 4, 4));
		grid.setOpaque(false);
		grid.setAlignmentX(Component.LEFT_ALIGNMENT);
		grid.add(statTile("Profit", Gp.signed(sum.profit), colorOf(sum.profit)));
		grid.add(statTile("GP / hour", start > 0 && perHour != 0 ? Gp.signed(perHour) : "—", colorOf(perHour)));
		grid.add(statTile("Flips", sum.flips + "  (" + sum.wins + "W / " + sum.losses + "L)", Color.WHITE));
		grid.add(statTile("ROI · tax paid", String.format(Locale.US, "%.1f%%", sum.roi()) + " · " + Gp.shortForm(sum.tax), Color.WHITE));
		grid.setMaximumSize(new Dimension(Integer.MAX_VALUE, grid.getPreferredSize().height));
		statsView.add(grid);
		statsView.add(Box.createVerticalStrut(4));

		if (sum.list.size() >= 2)
		{
			int n = sum.list.size();
			long[] x = new long[n + 1];
			long[] y = new long[n + 1];
			x[0] = sum.list.get(0).boughtAt > 0 ? sum.list.get(0).boughtAt : sum.list.get(0).time - 1;
			long total = 0;
			for (int i = 0; i < n; i++)
			{
				total += sum.list.get(i).profit;
				x[i + 1] = sum.list.get(i).time;
				y[i + 1] = total;
			}
			LineChart chart = new LineChart(90);
			chart.setSeries(Collections.singletonList(new LineChart.Series(x, y, total >= 0 ? GOOD : BAD)), true);
			chart.setToolTipText("Profit adding up over " + range.toString().toLowerCase(Locale.US));
			statsView.add(chart);
			statsView.add(Box.createVerticalStrut(4));
		}

		List<Map.Entry<Integer, long[]>> items = new ArrayList<>(sum.byItem.entrySet());
		items.sort(Comparator.comparingLong((Map.Entry<Integer, long[]> e) -> e.getValue()[0]).reversed());
		if (!items.isEmpty())
		{
			statsView.add(small("Best items", MUTED));
			for (int i = 0; i < items.size() && i < 3 && items.get(i).getValue()[0] > 0; i++)
			{
				statsView.add(itemLine(data, items.get(i)));
			}
			List<Map.Entry<Integer, long[]>> losers = new ArrayList<>();
			for (int i = items.size() - 1; i >= 0 && losers.size() < 3 && items.get(i).getValue()[0] < 0; i--)
			{
				losers.add(items.get(i));
			}
			if (!losers.isEmpty())
			{
				statsView.add(small("Worst items", MUTED));
				for (Map.Entry<Integer, long[]> e : losers)
				{
					statsView.add(itemLine(data, e));
				}
			}
		}
		else
		{
			statsView.add(small("No flips finished in this range.", MUTED));
		}

		statsView.add(heading("Held items"));
		Map<Integer, long[]> held = new java.util.LinkedHashMap<>();
		for (Ledger.Lot lot : lots)
		{
			long[] v = held.computeIfAbsent(lot.itemId, k -> new long[2]);
			v[0] += lot.qty;
			v[1] += lot.cost;
		}
		if (held.isEmpty())
		{
			statsView.add(small("Nothing bought and waiting to sell.", MUTED));
		}
		for (Map.Entry<Integer, long[]> e : held.entrySet())
		{
			int id = e.getKey();
			JPanel row = row();
			row.add(small(data.name(id) + " ×" + Gp.full(e.getValue()[0]) + " · cost " + Gp.shortForm(e.getValue()[1]), Color.WHITE), BorderLayout.CENTER);
			JButton forget = new JButton("Forget");
			forget.setToolTipText("Stop counting these, e.g. you used them or moved them off the GE");
			forget.setFont(FontManager.getRunescapeSmallFont());
			forget.addActionListener(ev -> plugin.forgetHeld(id));
			row.add(forget, BorderLayout.EAST);
			statsView.add(row);
		}

		statsView.add(heading("Buy limits (4 hours)"));
		if (limits.isEmpty())
		{
			statsView.add(small("No limits in use.", MUTED));
		}
		for (Map.Entry<Integer, Ledger.Window> e : limits)
		{
			PriceData.Item it = data.items.get(e.getKey());
			String cap = it == null || it.limit == null ? "?" : Gp.shortForm(it.limit);
			JPanel row = row();
			row.add(small(data.name(e.getKey()) + "  " + Gp.shortForm(e.getValue().bought) + "/" + cap, Color.WHITE), BorderLayout.CENTER);
			row.add(small(Gp.duration(e.getValue().start + Ledger.LIMIT_WINDOW_MS - now), MUTED), BorderLayout.EAST);
			row.setToolTipText("Buy limit resets in " + Gp.duration(e.getValue().start + Ledger.LIMIT_WINDOW_MS - now));
			statsView.add(row);
		}

		statsView.add(heading("Recent flips"));
		if (flips.isEmpty())
		{
			statsView.add(small("Flips show up here as your sells fill.", MUTED));
		}
		for (int i = flips.size() - 1, n = 0; i >= 0 && n < 40; i--, n++)
		{
			Ledger.Flip f = flips.get(i);
			JPanel row = row();
			row.add(small(when(f.time) + "  " + data.name(f.itemId) + " ×" + Gp.shortForm(f.qty), Color.WHITE), BorderLayout.CENTER);
			JLabel p = small(Gp.signed(f.profit), colorOf(f.profit));
			row.add(p, BorderLayout.EAST);
			row.setToolTipText("<html>Cost " + Gp.full(f.cost) + "<br>Sold for " + Gp.full(f.revenue) + "<br>Tax " + Gp.full(f.tax)
				+ "<br>Profit " + Gp.signed(f.profit) + "</html>");
			statsView.add(row);
		}
		if (untracked > 0)
		{
			statsView.add(Box.createVerticalStrut(4));
			statsView.add(note(Gp.full(untracked) + " items sold that weren't bought through the plugin (no profit counted)."));
		}
		if (!flips.isEmpty())
		{
			statsView.add(Box.createVerticalStrut(6));
			statsView.add(controls.copy);
			statsView.add(note("Copies your last " + flips.size() + " flips (the most the plugin keeps is "
				+ Ledger.KEEP_FLIPS + ")."));
		}
		statsView.add(heading("Start over"));
		statsView.add(controls.reset);
		statsView.add(note("Zeroes flips, profit and the bankroll. Held items and buy limits stay."));
		statsView.revalidate();
		statsView.repaint();
	}

	private static JPanel statTile(String label, String value, Color color)
	{
		JPanel t = column();
		t.setBackground(CARD);
		t.setOpaque(true);
		t.setBorder(new EmptyBorder(3, 5, 3, 5));
		t.add(small(label.toUpperCase(Locale.US), MUTED));
		t.add(small(value, color));
		return t;
	}

	private static JPanel itemLine(PriceData data, Map.Entry<Integer, long[]> e)
	{
		long[] v = e.getValue();
		JPanel row = row();
		row.add(small(data.name(e.getKey()) + " · " + v[2] + (v[2] == 1 ? " flip" : " flips"), Color.WHITE), BorderLayout.CENTER);
		row.add(small(Gp.signed(v[0]), colorOf(v[0])), BorderLayout.EAST);
		return row;
	}

	// ---------------------------------------------------------------- helpers

	private void addIcon(JLabel label, int itemId)
	{
		addIcon(itemManager, label, itemId);
	}

	private static void addIcon(ItemManager itemManager, JLabel label, int itemId)
	{
		AsyncBufferedImage img = itemManager == null ? null : itemManager.getImage(itemId);
		if (img != null)
		{
			img.addTo(label);
		}
	}

	private static String when(long millis)
	{
		Instant t = Instant.ofEpochMilli(millis);
		LocalDate day = t.atZone(ZoneId.systemDefault()).toLocalDate();
		return (day.equals(LocalDate.now()) ? TIME : DAY).format(t.atZone(ZoneId.systemDefault()));
	}

	private static long startOfToday()
	{
		return LocalDate.now().atStartOfDay(ZoneId.systemDefault()).toInstant().toEpochMilli();
	}

	private static Color colorOf(long n)
	{
		return n > 0 ? GOOD : n < 0 ? BAD : MUTED;
	}

	private static JPanel column()
	{
		JPanel p = new JPanel();
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		p.setOpaque(false);
		p.setAlignmentX(Component.LEFT_ALIGNMENT);
		return p;
	}

	/** A left-aligned, full-width row with content in the middle and something on the right. */
	private static JPanel row()
	{
		JPanel r = new JPanel(new BorderLayout(4, 0))
		{
			@Override
			public Dimension getMaximumSize()
			{
				return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
			}
		};
		r.setOpaque(false);
		r.setAlignmentX(Component.LEFT_ALIGNMENT);
		return r;
	}

	private static JPanel card()
	{
		// Full row width, own height: BoxLayout would otherwise shrink a card to its text.
		JPanel c = new JPanel()
		{
			@Override
			public Dimension getMaximumSize()
			{
				return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
			}
		};
		c.setLayout(new BoxLayout(c, BoxLayout.Y_AXIS));
		c.setOpaque(true);
		c.setBackground(CARD);
		c.setBorder(new EmptyBorder(5, 6, 5, 6));
		c.setAlignmentX(Component.LEFT_ALIGNMENT);
		return c;
	}

	private static JComponent left(JComponent c)
	{
		c.setAlignmentX(Component.LEFT_ALIGNMENT);
		return c;
	}

	private static JLabel small(String text, Color color)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(color);
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		return l;
	}

	/** A label that wraps inside the narrow panel instead of running off its edge. */
	private static JLabel wrap(String html, Color color)
	{
		JLabel l = new JLabel("<html><div style='width:170px'>" + html + "</div></html>");
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(color);
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		return l;
	}

	private static JLabel heading(String text)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeBoldFont());
		l.setForeground(ORANGE);
		l.setBorder(new EmptyBorder(10, 0, 3, 0));
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		return l;
	}

	private static JLabel note(String text)
	{
		// A fixed wrap width lets the label work out its real height inside the narrow side panel.
		JLabel l = new JLabel("<html><div style='width:165px'>" + text + "</div></html>");
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(MUTED);
		l.setBorder(new EmptyBorder(3, 0, 3, 0));
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		return l;
	}

	private static JPanel labeled(String label, JComponent field)
	{
		JPanel p = column();
		p.add(small(label, MUTED));
		field.setAlignmentX(Component.LEFT_ALIGNMENT);
		field.setMaximumSize(new Dimension(Integer.MAX_VALUE, field.getPreferredSize().height));
		p.add(field);
		return p;
	}

	/** Scroll content that always matches the panel's width, so long text can't push buttons off the edge. */
	private static final class FitWidth extends JPanel implements Scrollable
	{
		FitWidth()
		{
			super(new BorderLayout());
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle r, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle r, int orientation, int direction)
		{
			return r.height;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}

	private static JScrollPane scroll(JPanel content)
	{
		JPanel wrap = new FitWidth();
		wrap.setBackground(ColorScheme.DARK_GRAY_COLOR);
		wrap.setBorder(new EmptyBorder(4, 8, 8, 8));
		wrap.add(content, BorderLayout.NORTH);
		JScrollPane sp = new JScrollPane(wrap, ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
			ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		sp.setBorder(null);
		sp.getVerticalScrollBar().setUnitIncrement(16);
		return sp;
	}
}

