package com.merchtool;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import com.google.gson.Gson;
import com.google.inject.Guice;
import com.google.inject.Injector;
import com.merchtool.core.Ledger;
import java.util.HashMap;
import java.util.Map;
import java.util.EnumSet;
import java.util.concurrent.ScheduledExecutorService;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.WorldType;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ClientToolbar;
import okhttp3.OkHttpClient;
import net.runelite.client.events.RuneScapeProfileChanged;
import org.junit.Before;
import org.junit.Test;

/** Drives the real plugin through a trading session with a fake game client. */
public class PluginFlowTest
{
	private static final int WHIP = 4151;
	private static final int DEATH_RUNE = 560;

	private Client client;
	private MerchConfig config;
	private MerchPlugin plugin;
	private int tick;
	private GrandExchangeOffer[] clientOffers;
	private final Notifier notifier = mock(Notifier.class);

	/** Stands in for RuneLite's per-account settings. */
	private final Map<String, String> profileConfig = new HashMap<>();
	private String rsProfile = "rsprofile.main";

	@Before
	public void setUp() throws Exception
	{
		client = mock(Client.class);
		config = mock(MerchConfig.class);
		when(client.getAccountHash()).thenReturn(42L);
		when(client.getWorldType()).thenReturn(EnumSet.noneOf(WorldType.class));
		when(client.getTickCount()).thenAnswer(i -> tick);
		clientOffers = new GrandExchangeOffer[8];
		for (int i = 0; i < 8; i++)
		{
			clientOffers[i] = offer(0, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0);
		}
		when(client.getGrandExchangeOffers()).thenAnswer(i -> clientOffers);
		plugin = newPlugin();
	}

	/** Builds the plugin the way RuneLite does: Guice injects mocks for everything it needs. */
	private MerchPlugin newPlugin() throws Exception
	{
		ScheduledExecutorService direct = mock(ScheduledExecutorService.class);
		doAnswer(i -> {
			((Runnable) i.getArgument(0)).run();
			return null;
		}).when(direct).execute(any());
		ConfigManager cm = mock(ConfigManager.class);
		when(cm.getRSProfileKey()).thenAnswer(i -> rsProfile);
		when(cm.getConfiguration(anyString(), anyString(), anyString()))
			.thenAnswer(i -> profileConfig.get(i.getArgument(1) + "/" + i.getArgument(2)));
		doAnswer(i -> {
			profileConfig.put(i.getArgument(1) + "/" + i.getArgument(2), i.getArgument(3));
			return null;
		}).when(cm).setConfiguration(anyString(), anyString(), anyString(), anyString());

		Injector injector = Guice.createInjector(binder -> {
			binder.bind(Client.class).toInstance(client);
			binder.bind(ClientThread.class).toInstance(mock(ClientThread.class));
			binder.bind(MerchConfig.class).toInstance(config);
			binder.bind(ConfigManager.class).toInstance(cm);
			binder.bind(OkHttpClient.class).toInstance(mock(OkHttpClient.class));
			binder.bind(Gson.class).toInstance(new Gson());
			binder.bind(ScheduledExecutorService.class).toInstance(direct);
			binder.bind(ClientToolbar.class).toInstance(mock(ClientToolbar.class));
			binder.bind(ItemManager.class).toInstance(mock(ItemManager.class));
			binder.bind(Notifier.class).toInstance(notifier);
		});
		MerchPlugin p = injector.getInstance(MerchPlugin.class);
		p.startUp();
		return p;
	}

	private static GrandExchangeOffer offer(int itemId, GrandExchangeOfferState state, int total, long price, int sold, long spent)
	{
		return new GrandExchangeOffer()
		{
			public int getQuantitySold()
			{
				return sold;
			}

			public int getItemId()
			{
				return itemId;
			}

			public int getTotalQuantity()
			{
				return total;
			}

			public long getPrice()
			{
				return price;
			}

			public long getSpent()
			{
				return spent;
			}

			public GrandExchangeOfferState getState()
			{
				return state;
			}
		};
	}

	private void event(int slot, int itemId, GrandExchangeOfferState state, int total, long price, int sold, long spent)
	{
		GrandExchangeOffer o = offer(itemId, state, total, price, sold, spent);
		clientOffers[slot] = o;
		GrandExchangeOfferChanged e = new GrandExchangeOfferChanged();
		e.setSlot(slot);
		e.setOffer(o);
		// The game sends most events twice.
		plugin.onGrandExchangeOfferChanged(e);
		plugin.onGrandExchangeOfferChanged(e);
	}

	private void gameState(GameState s)
	{
		when(client.getGameState()).thenReturn(s);
		GameStateChanged e = new GameStateChanged();
		e.setGameState(s);
		plugin.onGameStateChanged(e);
	}

	private void ticks(int n)
	{
		for (int i = 0; i < n; i++)
		{
			tick++;
			plugin.onGameTick(new GameTick());
		}
	}

	@Test
	public void splitSettingSharesFreeGoldAcrossEmptySlots()
	{
		tick = 100;
		gameState(GameState.LOGGED_IN);
		plugin.setBankroll(8_000_000);
		ticks(5);
		when(client.getWorldType()).thenReturn(EnumSet.of(WorldType.MEMBERS));

		// Off: one suggestion that may use all the free gold.
		assertEquals(8_000_000, plugin.dealCash());
		assertEquals(1, plugin.suggestions());

		// On, all 8 slots empty: each suggestion gets an eighth.
		when(config.splitSlots()).thenReturn(true);
		assertEquals(1_000_000, plugin.dealCash());
		assertEquals(8, plugin.suggestions());

		// A live buy takes a slot and its gold: 6m left over 7 empty slots.
		event(0, WHIP, GrandExchangeOfferState.BUYING, 2, 1_000_000, 0, 0);
		assertEquals(6_000_000 / 7, plugin.dealCash());
		assertEquals(7, plugin.suggestions());

		// A free world only has 3 slots, 2 of them empty.
		when(client.getWorldType()).thenReturn(EnumSet.noneOf(WorldType.class));
		assertEquals(3_000_000, plugin.dealCash());
		assertEquals(2, plugin.suggestions());
	}

	@Test
	public void fullSessionTracksSlotsAndProfit() throws Exception
	{
		// Logging in: the game reports slots before the account is known.
		tick = 100;
		gameState(GameState.LOGGING_IN);
		event(0, 0, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0);
		gameState(GameState.LOGGED_IN);
		assertNotNull(plugin.ledger());
		plugin.setBankroll(10_000_000);
		ticks(5);

		// Place a whip buy in-game: the slot fills itself in.
		event(0, WHIP, GrandExchangeOfferState.BUYING, 6, 1_480_001, 0, 0);
		assertEquals(WHIP, plugin.slots()[0].itemId);
		assertEquals(6 * 1_480_001L, plugin.escrow());
		assertEquals(10_000_000 - 6 * 1_480_001L, plugin.ledger().freeGold(plugin.escrow()));

		ticks(3);
		event(0, WHIP, GrandExchangeOfferState.BUYING, 6, 1_480_001, 4, 4 * 1_479_500L);
		assertEquals(4, plugin.ledger().heldQty(WHIP));
		event(0, WHIP, GrandExchangeOfferState.BUYING, 6, 1_480_001, 6, 6 * 1_479_500L);
		event(0, WHIP, GrandExchangeOfferState.BOUGHT, 6, 1_480_001, 6, 6 * 1_479_500L);
		assertEquals(6, plugin.ledger().heldQty(WHIP));
		assertEquals(6, plugin.ledger().limitUsed(WHIP, System.currentTimeMillis()));
		assertEquals(0, plugin.escrow());

		// Collect, then sell.
		event(0, 0, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0);
		assertNull(plugin.slots()[0]);
		event(0, WHIP, GrandExchangeOfferState.SELLING, 6, 1_519_999, 0, 0);
		event(0, WHIP, GrandExchangeOfferState.SELLING, 6, 1_519_999, 2, 2 * 1_519_999L);
		event(0, WHIP, GrandExchangeOfferState.SOLD, 6, 1_519_999, 6, 6 * 1_519_999L);
		Ledger l = plugin.ledger();
		long perItem = 1_519_999 - 30_399 - 1_479_500;
		assertEquals(2, l.flips.size());
		assertEquals(6 * perItem, l.profitSince(0));
		assertEquals(10_000_000 + 6 * perItem, l.bankroll());

		// A death rune buy is half done when we hop worlds; 20 more fill during the hop.
		event(1, DEATH_RUNE, GrandExchangeOfferState.BUYING, 100, 200, 10, 2_000);
		gameState(GameState.HOPPING);
		gameState(GameState.LOGGED_IN);
		event(1, 0, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0);
		event(1, DEATH_RUNE, GrandExchangeOfferState.BUYING, 100, 200, 30, 6_000);
		assertEquals(30, plugin.ledger().heldQty(DEATH_RUNE));
		ticks(5);

		// Log out. While away, the runes finish on mobile and get collected; the whip slot was already empty.
		gameState(GameState.LOGIN_SCREEN);
		assertNull(plugin.ledger());
		clientOffers[1] = offer(0, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0);

		// Fresh plugin instance, same account: everything comes back from disk.
		plugin = newPlugin();
		tick = 500;
		gameState(GameState.LOGGED_IN);
		event(1, 0, GrandExchangeOfferState.EMPTY, 0, 0, 0, 0);   // login burst: ignored...
		assertNotNull(plugin.slots()[1]);
		ticks(4);                                               // ...then reconciled against the game
		assertNull(plugin.slots()[1]);
		assertEquals(2, plugin.ledger().flips.size());
		assertEquals(10_000_000 + 6 * perItem, plugin.ledger().bankroll());
		assertEquals(30, plugin.ledger().heldQty(DEATH_RUNE));
	}

	@Test
	public void seasonalWorldsAreIgnored()
	{
		tick = 10;
		gameState(GameState.LOGGED_IN);
		when(client.getWorldType()).thenReturn(EnumSet.of(WorldType.SEASONAL));
		event(2, WHIP, GrandExchangeOfferState.BUYING, 1, 1_000_000, 1, 1_000_000);
		assertNull(plugin.slots()[2]);
	}

	@Test
	public void eachAccountKeepsItsOwnData() throws Exception
	{
		tick = 1;
		gameState(GameState.LOGGED_IN);
		plugin.setBankroll(5_000_000);
		assertNotNull(profileConfig.get("rsprofile.main/account"));
		gameState(GameState.LOGIN_SCREEN);

		// A different account logs in: fresh books, and the first account's are untouched.
		rsProfile = "rsprofile.alt";
		gameState(GameState.LOGGED_IN);
		assertEquals(0, plugin.ledger().bankrollStart);
		plugin.setBankroll(1_000);
		gameState(GameState.LOGIN_SCREEN);
		rsProfile = "rsprofile.main";
		gameState(GameState.LOGGED_IN);
		assertEquals(5_000_000, plugin.ledger().bankrollStart);
	}

	@Test
	public void loadsWhenProfileArrivesAfterLogin()
	{
		rsProfile = null;
		tick = 1;
		gameState(GameState.LOGGED_IN);
		assertNull(plugin.ledger());
		rsProfile = "rsprofile.main";
		plugin.onRuneScapeProfileChanged(new RuneScapeProfileChanged(null, "rsprofile.main"));
		assertNotNull(plugin.ledger());
	}

	@Test
	public void starsAndSessionFollowTheAccount() throws Exception
	{
		tick = 1;
		gameState(GameState.LOGGED_IN);
		assertTrue(plugin.sessionStart() > 0);
		plugin.toggleStar(WHIP);
		plugin.toggleStar(DEATH_RUNE);
		plugin.toggleStar(DEATH_RUNE);
		assertEquals(java.util.Collections.singleton(WHIP), plugin.starred());
		gameState(GameState.LOGIN_SCREEN);
		assertEquals(0, plugin.sessionStart());
		assertTrue(plugin.starred().isEmpty());

		plugin = newPlugin();
		gameState(GameState.LOGGED_IN);
		assertEquals(java.util.Collections.singleton(WHIP), plugin.starred());
	}
}

package com.merchtool.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.HashMap;
