public class CoreTest
{
	private static final int WHIP = 4151;

	// ---------- tax ----------

	@Test
	public void taxRules()
	{
		assertEquals(0, GeTax.perItem(WHIP, 49));
		assertEquals(1, GeTax.perItem(WHIP, 50));
		assertEquals(1, GeTax.perItem(WHIP, 99));
		assertEquals(30_399, GeTax.perItem(WHIP, 1_519_999));
		assertEquals(4_999_999, GeTax.perItem(WHIP, 249_999_999));
		assertEquals(5_000_000, GeTax.perItem(WHIP, 250_000_000));
		assertEquals(5_000_000, GeTax.perItem(WHIP, 5_000_000_000L));
		assertEquals(0, GeTax.perItem(ItemID.OSRS_BOND, 9_000_000));
		assertEquals(0, GeTax.perItem(ItemID.LOBSTER, 200));
		assertEquals(0, GeTax.perItem(ItemID.MINDRUNE, 60));
		// Filled watering cans are taxed; only the empty one is exempt.
		assertEquals(2, GeTax.perItem(ItemID.WATERING_CAN_0 + 2, 100));
	}

	@Test
	public void gpParseAndFormat()
	{
		assertEquals(1_500_000, Gp.parse("1.5m"));
		assertEquals(250_000, Gp.parse("250k"));
		assertEquals(2_000_000_000L, Gp.parse("2b"));
		assertEquals(1234, Gp.parse("1,234"));
		assertEquals(-1, Gp.parse("lots"));
		assertEquals("1.52M", Gp.shortForm(1_519_999));
		assertEquals("12.5K", Gp.shortForm(12_500));
		assertEquals("+9,599", Gp.signed(9_599));
	}

	// ---------- market ----------

	private static PriceData data(long low, long high, long lowAgo, long highAgo, long now)
	{
		return data(WHIP, low, high, lowAgo, highAgo, now);
	}

	private static PriceData data(int id, long low, long high, long lowAgo, long highAgo, long now)
	{
		PriceData.Item it = new PriceData.Item();
		it.id = id;
		it.name = "Abyssal whip";
		it.members = true;
		it.limit = 70;
		PriceData.Latest l = new PriceData.Latest();
		l.low = low;
		l.high = high;
		l.lowTime = now - lowAgo;
		l.highTime = now - highAgo;
		PriceData.Avg a = new PriceData.Avg();
		a.avgLowPrice = low;
		a.avgHighPrice = high;
		a.lowPriceVolume = 320;
		a.highPriceVolume = 300;
		Map<Integer, PriceData.Avg> avg = new HashMap<>();
		avg.put(id, a);
		return new PriceData(Map.of(id, it), Map.of(id, l), avg, avg, now);
	}

	@Test
	public void dealUsesOfferPricesAndTax()
	{
		long now = 1_000_000;
		Market.Deal d = Market.evaluate(data(1_480_000, 1_520_000, 30, 30, now), WHIP, 10_000_000, 0);
		assertEquals(1_480_001, d.offerBuy);
		assertEquals(1_519_999, d.offerSell);
		assertEquals(30_399, d.tax);
		assertEquals(9_599, d.margin);
		assertEquals(6, d.maxQty);          // 10m free / 1,480,001
		assertEquals(57_594, d.potProfit);
		assertFalse(d.spike);
		// Buy limit used up -> nothing left to buy.
		assertEquals(0, Market.evaluate(data(1_480_000, 1_520_000, 30, 30, now), WHIP, -1, 70).maxQty);
		// No bankroll -> capped by the limit only.
		assertEquals(70, Market.evaluate(data(1_480_000, 1_520_000, 30, 30, now), WHIP, -1, 0).maxQty);
	}

	@Test
	public void tightSpreadDoesNotStepInside()
	{
		Market.Deal d = Market.evaluate(data(18, 20, 1, 1, 100), WHIP, -1, 0);
		assertEquals(18, d.offerBuy);
		assertEquals(20, d.offerSell);
	}

	@Test
	public void staleAndSpikyDealsAreFiltered()
	{
		long now = 1_000_000;
		Market.Filters f = new Market.Filters();
		PriceData fresh = data(1_480_000, 1_520_000, 30, 30, now);
		assertEquals(1, Market.rank(fresh, f, -1, id -> 0, Set.of(), now).size());
		PriceData stale = data(1_480_000, 1_520_000, 30, 3600, now);
		assertEquals(0, Market.rank(stale, f, -1, id -> 0, Set.of(), now).size());
		// Latest sell far above the hour's average: a burst of overpaying, not a real margin.
		PriceData spike = data(1_480_000, 1_520_000, 30, 30, now);
		spike.avg1h.get(WHIP).avgHighPrice = 1_000_000L;
		List<Market.Deal> r = Market.rank(spike, f, -1, id -> 0, Set.of(), now);
		assertEquals(0, r.size());
		assertEquals(0, Market.rank(fresh, f, -1, id -> 0, Set.of(WHIP), now).size());
	}

	@Test
	public void bondsCanBeLeftOut()
	{
		long now = 1_000_000;
		Market.Filters f = new Market.Filters();
		PriceData bond = data(ItemID.OSRS_BOND, 8_000_000, 8_400_000, 30, 30, now);
		assertEquals(1, Market.rank(bond, f, -1, id -> 0, Set.of(), now).size());
		f.includeBonds = false;
		assertEquals(0, Market.rank(bond, f, -1, id -> 0, Set.of(), now).size());
		// Other items are untouched by the bond setting.
		assertEquals(1, Market.rank(data(1_480_000, 1_520_000, 30, 30, now), f, -1, id -> 0, Set.of(), now).size());
	}

	// ---------- offer tracking ----------

	@Test
	public void buyOfferFillsAndCompletesWithoutDoubleCounting()
	{
		OfferTracker t = new OfferTracker();
		assertNull(t.update(0, WHIP, "BUYING", 6, 1_480_001, 0, 0, false, 1));
		assertNull(t.update(0, WHIP, "BUYING", 6, 1_480_001, 0, 0, false, 1));       // duplicate
		OfferTracker.Fill f = t.update(0, WHIP, "BUYING", 6, 1_480_001, 4, 5_919_000, false, 2);
		assertEquals(4, f.qty);
		assertEquals(5_919_000, f.gold);
		assertNull(t.update(0, WHIP, "BUYING", 6, 1_480_001, 4, 5_919_000, false, 2)); // duplicate
		f = t.update(0, WHIP, "BUYING", 6, 1_480_001, 6, 8_879_000, false, 3);       // redundant pre-completion event
		assertEquals(2, f.qty);
		assertEquals(2_960_000, f.gold);
		assertNull(t.update(0, WHIP, "BOUGHT", 6, 1_480_001, 6, 8_879_000, false, 3));
		assertTrue(t.slots[0].isDone());
		assertEquals(0, t.totalEscrow());
		assertNull(t.update(0, 0, "EMPTY", 0, 0, 0, 0, false, 4));                   // collected
		assertNull(t.slots[0]);
	}

	@Test
	public void escrowIsUnfilledGoldOnly()
	{
		OfferTracker t = new OfferTracker();
		t.update(1, WHIP, "BUYING", 10, 1_000, 3, 3_000, false, 1);
		assertEquals(7_000, t.totalEscrow());
		t.update(1, WHIP, "CANCELLED_BUY", 10, 1_000, 3, 3_000, false, 2);
		assertEquals(0, t.totalEscrow());
	}

	@Test
	public void loginBurstDoesNotRecountOrWipe()
	{
		OfferTracker t = new OfferTracker();
		t.update(2, WHIP, "SELLING", 5, 1_519_999, 1, 1_519_999, false, 1);
		// Login: EMPTY first (ignored), then the real state with 2 more sold while logged out.
		assertNull(t.update(2, 0, "EMPTY", 0, 0, 0, 0, true, 10));
		assertNotNull(t.slots[2]);
		OfferTracker.Fill f = t.update(2, WHIP, "SELLING", 5, 1_519_999, 3, 4_559_997, true, 10);
		assertEquals(2, f.qty);
		// An offer seen for the first time at login with nothing saved is only a starting point.
		assertNull(t.update(3, WHIP, "BUYING", 5, 1_000, 2, 2_000, true, 10));
		assertEquals(2, t.slots[3].filled);
		assertEquals(0, t.slots[3].placedAt);
	}

	@Test
	public void offerPlacedFromAnotherDeviceCountsItsFills()
	{
		OfferTracker t = new OfferTracker();
		t.update(4, WHIP, "BOUGHT", 2, 1_000, 2, 2_000, false, 1);
		// Collected and replaced on mobile: at login the slot holds a different offer that already filled 3.
		OfferTracker.Fill f = t.update(4, 560, "BUYING", 1000, 200, 3, 600, true, 10);
		assertEquals(3, f.qty);
		assertEquals(560, f.itemId);
	}

	// ---------- ledger ----------

	@Test
	public void flipProfitAfterTaxFifo()
	{
		Ledger l = new Ledger();
		l.setBankroll(10_000_000, 0);
		l.recordBuy(WHIP, 4, 4 * 1_480_001L, 1);
		l.recordBuy(WHIP, 2, 2 * 1_490_000L, 2);
		assertEquals(10_000_000 - 4 * 1_480_001L - 2 * 1_490_000L, l.freeGold(0));
		// Sell 5 at 1,519,999: matches 4 @1,480,001 then 1 @1,490,000.
		Ledger.Flip f = l.recordSell(WHIP, 5, 5 * 1_519_999L, 3);
		assertEquals(5, f.qty);
		assertEquals(5 * 30_399L, f.tax);
		assertEquals(5 * 1_519_999L - 5 * 30_399L - (4 * 1_480_001L + 1_490_000L), f.profit);
		assertEquals(1, l.heldQty(WHIP));
		assertEquals(1_490_000, l.heldAvgCost(WHIP));
		assertEquals(10_000_000 + f.profit, l.bankroll());
		assertEquals(6, l.limitUsed(WHIP, 3));
		assertEquals(0, l.limitUsed(WHIP, 1 + Ledger.LIMIT_WINDOW_MS));
	}

	@Test
	public void lossesAndUntrackedSales()
	{
		Ledger l = new Ledger();
		l.recordBuy(WHIP, 1, 1_480_001, 1);
		Ledger.Flip f = l.recordSell(WHIP, 1, 1_400_000, 2);
		assertEquals(1_400_000 - 28_000 - 1_480_001, f.profit);
		// Selling something never bought through the plugin: no fake profit.
		assertNull(l.recordSell(WHIP, 3, 4_500_000, 3));
		assertEquals(3, l.untrackedSold);
	}

	@Test
	public void resetStatsKeepsHeldItemsAndLimits()
	{
		Ledger l = new Ledger();
		l.setBankroll(10_000_000, 0);
		l.recordBuy(WHIP, 3, 3 * 1_480_001L, 1);
		l.recordSell(WHIP, 1, 1_519_999, 2);
		l.recordSell(WHIP, 4, 4 * 1_519_999L, 3);   // 2 matched, 2 untracked
		l.recordBuy(WHIP, 1, 1_480_001, 4);
		l.resetStats();
		assertTrue(l.flips.isEmpty());
		assertEquals(0, l.profitSince(0));
		assertEquals(0, l.wins());
		assertEquals(0, l.untrackedSold);
		assertFalse(l.hasBankroll());
		assertEquals(1, l.heldQty(WHIP));
		assertEquals(4, l.limitUsed(WHIP, 4));
	}

	@Test
	public void compactKeepsTotalsExact()
	{
		Ledger l = new Ledger();
		l.setBankroll(1_000_000, 0);
		long expected = 0;
		for (int i = 0; i < Ledger.KEEP_FLIPS + 50; i++)
		{
			l.recordBuy(WHIP, 1, 1_000, i * 10L);
			long sale = i % 3 == 0 ? 900 : 1_200;   // every third flip loses
			Ledger.Flip f = l.recordSell(WHIP, 1, sale, i * 10L + 5);
			expected += f.profit;
		}
		int wins = l.wins();
		int losses = l.losses();
		l.compact(Ledger.LIMIT_WINDOW_MS * 10);
		assertEquals(Ledger.KEEP_FLIPS, l.flips.size());
		assertEquals(expected, l.profitSince(0));
		assertEquals(1_000_000 + expected, l.bankroll());
		assertEquals(wins, l.wins());
		assertEquals(losses, l.losses());
		assertTrue(l.limits.isEmpty());
	}
}

package com.merchtool.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.time.ZoneOffset;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/** The add-ons: stats by range, limit-reset alerts, offer advice, alch/decant/set flips, price drops, CSV. */
public class FeaturesTest
{
	private static final int WHIP = 4151;
	private static final long NOW = 1_800_000_000L;

	/** Builds a price snapshot item by item. */
	private static final class Prices
	{
		final Map<Integer, PriceData.Item> items = new HashMap<>();
		final Map<Integer, PriceData.Latest> latest = new HashMap<>();
		final Map<Integer, PriceData.Avg> avg = new HashMap<>();

		Prices add(int id, String name, long low, long high, Integer limit, Long highalch)
		{
			PriceData.Item it = new PriceData.Item();
			it.id = id;
			it.name = name;
			it.members = true;
			it.limit = limit;
			it.highalch = highalch;
			items.put(id, it);
			PriceData.Latest l = new PriceData.Latest();
			l.low = low;
			l.high = high;
			l.lowTime = NOW - 30;
			l.highTime = NOW - 30;
			latest.put(id, l);
			PriceData.Avg a = new PriceData.Avg();
			a.avgLowPrice = low;
			a.avgHighPrice = high;
			a.lowPriceVolume = 500;
			a.highPriceVolume = 500;
			avg.put(id, a);
			return this;
		}

		PriceData build()
		{
			return new PriceData(items, latest, avg, avg, NOW);
		}
	}

	private static Market.Filters filters()
	{
		Market.Filters f = new Market.Filters();
		f.maxAgeMinutes = 10;
		return f;
	}

	// ---------- stats by range ----------

	@Test
	public void summaryByRangeWithGpPerHour()
	{
		Ledger l = new Ledger();
		long h = 3600_000L;
		l.recordBuy(WHIP, 10, 10_000_000, h);
		l.recordSell(WHIP, 10, 11_000_000, 3 * h); // 11m - 220k tax - 10m = +780k
		l.recordBuy(560, 1000, 200_000, 4 * h);
		l.recordSell(560, 1000, 190_000, 5 * h); // 190k - 3,000 tax (190 each / 50 = 3) - 200k = -13k

		Ledger.Summary all = l.summary(0);
		assertEquals(780_000 - 13_000, all.profit);
		assertEquals(2, all.flips);
		assertEquals(1, all.wins);
		assertEquals(1, all.losses);
		assertEquals(h, all.firstBuy);
		assertEquals(220_000 + 3_000, all.tax);
		assertEquals(780_000, all.byItem.get(WHIP)[0]);
		assertEquals(-13_000, all.byItem.get(560)[0]);
		// 767k over the 4 hours from the first buy.
		assertEquals(767_000 / 4, all.perHour(all.firstBuy, 5 * h));

		Ledger.Summary late = l.summary(4 * h);
		assertEquals(-13_000, late.profit);
		assertEquals(4 * h, late.firstBuy);
		assertEquals(1, late.list.size());
		// Too short to mean anything.
		assertEquals(0, late.perHour(5 * h, 5 * h + 60_000));
	}

	// ---------- buy limit reset alerts ----------

	@Test
	public void limitResetAlertsOnceOnlyWhenTheLimitWasUsedUp()
	{
		Ledger l = new Ledger();
		l.recordBuy(WHIP, 70, 1, 0);       // used up (limit 70)
		l.recordBuy(560, 100, 1, 0);       // limit 25,000: not used up
		java.util.function.IntFunction<Integer> limits = id -> id == WHIP ? 70 : 25_000;

		assertTrue(l.limitResets(Ledger.LIMIT_WINDOW_MS - 1, limits, Ledger.ALERT_GRACE_MS).isEmpty());
		assertEquals(Collections.singletonList(WHIP), l.limitResets(Ledger.LIMIT_WINDOW_MS + 1000, limits, Ledger.ALERT_GRACE_MS));
		assertTrue("only once", l.limitResets(Ledger.LIMIT_WINDOW_MS + 2000, limits, Ledger.ALERT_GRACE_MS).isEmpty());

		// A reset long ago (logged out at the time) isn't alerted late.
		Ledger old = new Ledger();
		old.recordBuy(WHIP, 70, 1, 0);
		assertTrue(old.limitResets(Ledger.LIMIT_WINDOW_MS + 3600_000L, limits, Ledger.ALERT_GRACE_MS).isEmpty());

		// Saving keeps a just-expired window until its alert has had a chance to go out.
		Ledger keep = new Ledger();
		keep.recordBuy(WHIP, 70, 1, 0);
		keep.compact(Ledger.LIMIT_WINDOW_MS + 1000);
		assertEquals(1, keep.limitResets(Ledger.LIMIT_WINDOW_MS + 2000, limits, Ledger.ALERT_GRACE_MS).size());
	}

	// ---------- adjust or cancel ----------

	private static OfferTracker.Slot slot(boolean buy, long price, long lastActivity)
	{
		OfferTracker.Slot s = new OfferTracker.Slot();
		s.itemId = WHIP;
		s.buy = buy;
		s.total = 10;
		s.price = price;
		s.state = buy ? "BUYING" : "SELLING";
		s.lastActivity = lastActivity;
		return s;
	}

	private static Market.Deal market(long low, long high)
	{
		return Market.evaluate(new Prices().add(WHIP, "Abyssal whip", low, high, 70, null).build(), WHIP, -1, 0);
	}

	@Test
	public void adviceForBuyOffers()
	{
		long now = 10 * 60_000L;
		long stale = 5 * 60_000L;
		// Fine: not outbid, still profitable, filling.
		assertNull(Advice.forSlot(slot(true, 1_500_000, now), market(1_500_000, 1_600_000), 0, now, stale));

		// Outbid, but there's still a margin at the new price.
		Advice.Tip t = Advice.forSlot(slot(true, 1_500_000, now), market(1_510_000, 1_600_000), 0, now, stale);
		assertTrue(t.urgent);
		assertTrue(t.text, t.text.startsWith("Outbid. Re-place at 1,510,001"));

		// Outbid and no margin left: cancel.
		t = Advice.forSlot(slot(true, 1_500_000, now), market(1_580_000, 1_600_000), 0, now, stale);
		assertTrue(t.text, t.text.contains("Cancel"));

		// The sell side fell under what you're paying.
		t = Advice.forSlot(slot(true, 1_500_000, now), market(1_400_000, 1_500_000), 0, now, stale);
		assertTrue(t.text, t.text.contains("no longer makes a profit"));

		// No fills for a while and the market moved up a little: a gentle nudge.
		t = Advice.forSlot(slot(true, 1_500_000, 0), market(1_500_000, 1_600_000), 0, now, stale);
		assertFalse(t.urgent);
		assertTrue(t.text, t.text.startsWith("No fills for 10m 0s. Try 1,500,001"));

		// Done offers get no advice.
		OfferTracker.Slot done = slot(true, 1_500_000, 0);
		done.state = "BOUGHT";
		assertNull(Advice.forSlot(done, market(1_510_000, 1_600_000), 0, now, stale));
	}

	@Test
	public void adviceForSellOffers()
	{
		long now = 60_000L;
		// Undercut; re-listing still beats what you paid.
		Advice.Tip t = Advice.forSlot(slot(false, 1_600_000, now), market(1_500_000, 1_590_000), 1_500_000, now, 300_000);
		assertTrue(t.urgent);
		// 1,589,999 - 31,799 tax - 1,500,000 = +58,200
		assertEquals("Undercut. Re-list at 1,589,999 (still +58.2K ea)", t.text);

		// Undercut below cost: say what it loses.
		t = Advice.forSlot(slot(false, 1_600_000, now), market(1_400_000, 1_500_000), 1_500_000, now, 300_000);
		assertTrue(t.text, t.text.contains("loses"));

		// Listed at or under the market: fine.
		assertNull(Advice.forSlot(slot(false, 1_590_000, now), market(1_500_000, 1_600_000), 1_500_000, now, 300_000));
	}

	// ---------- alch, decant, sets ----------

	@Test
	public void highAlchFlips()
	{
		PriceData d = new Prices()
			.add(ItemID.NATURERUNE, "Nature rune", 100, 104, 18_000, 108L)
			.add(1, "Rune platebody", 38_000, 38_500, 70, 39_000L)  // 39,000 - 38,001 - 101 = +898
			.add(2, "Losing item", 10_000, 10_200, 70, 10_000L)
			.build();
		List<Recipes.Result> r = Recipes.rank(Recipes.Kind.ALCH, d, filters(), -1, id -> 0, NOW);
		assertEquals(1, r.size());
		Recipes.Result x = r.get(0);
		assertEquals("Rune platebody", x.name);
		assertEquals(38_001 + 101, x.cost);
		assertEquals(898, x.profit);
		assertEquals(70, x.batches);
		assertEquals(898 * 70, x.potProfit);
	}

	@Test
	public void decantingMatchesDosesAndSkipsJewellery()
	{
		PriceData d = new Prices()
			.add(10, "Prayer potion(3)", 7_000, 7_100, 2_000, null)
			.add(11, "Prayer potion(4)", 10_000, 10_500, 2_000, null)
			.add(20, "Amulet of glory(3)", 1, 2, 10_000, null)
			.add(21, "Amulet of glory(4)", 12_000, 12_500, 10_000, null)
			.build();
		List<Recipes.Result> r = Recipes.rank(Recipes.Kind.DECANT, d, filters(), -1, id -> 0, NOW);
		assertEquals(1, r.size());
		Recipes.Result x = r.get(0);
		assertEquals("Prayer potion (3) to (4)", x.name);
		// 4 x (3) at 7,001 = 28,004 in; 3 x (4) at 10,499 less 209 tax each = 30,870 out.
		assertEquals(28_004, x.cost);
		assertEquals(30_870, x.revenue);
		assertEquals(2_866, x.profit);
		// Half of 4 hours of (3) sell-offs: 500/hr x 4 / 2 = 1,000 potions = 250 batches of 4.
		assertEquals(250, x.batches);
	}

	@Test
	public void itemSetsPackAndUnpack()
	{
		// Rune armour set (lg): set 13024; pieces full helm 1163, platebody 1127, platelegs 1079, kiteshield 1201.
		Prices p = new Prices()
			.add(1163, "Rune full helm", 20_000, 20_200, 70, null)
			.add(1127, "Rune platebody", 38_000, 38_400, 70, null)
			.add(1079, "Rune platelegs", 37_000, 37_400, 70, null)
			.add(1201, "Rune kiteshield", 31_000, 31_400, 70, null)
			.add(13024, "Rune armour set (lg)", 128_000, 135_000, 8, null);
		List<Recipes.Result> r = Recipes.rank(Recipes.Kind.SET, p.build(), filters(), -1, id -> 0, NOW);
		assertEquals(1, r.size());
		Recipes.Result x = r.get(0);
		assertEquals("Rune armour set (lg): pack", x.name);
		assertEquals(20_001 + 38_001 + 37_001 + 31_001, x.cost);
		assertEquals(134_999 - 2_699, x.revenue);
		// The set's own buy limit (8) doesn't matter when you only sell sets; the pieces' limits (70) do.
		assertEquals(70, x.batches);
		assertEquals(Arrays.asList(1163, 1127, 1079, 1201), Arrays.asList(x.buy.get(0).itemId, x.buy.get(1).itemId,
			x.buy.get(2).itemId, x.buy.get(3).itemId));
	}

	@Test
	public void recipesRespectFreeGold()
	{
		PriceData d = new Prices()
			.add(ItemID.NATURERUNE, "Nature rune", 100, 104, 18_000, 108L)
			.add(1, "Rune platebody", 38_000, 38_500, 70, 39_000L)
			.build();
		Recipes.Result x = Recipes.rank(Recipes.Kind.ALCH, d, filters(), 381_020, id -> 0, NOW).get(0);
		assertEquals(10, x.batches);
		// And the buy limit already used this window.
		x = Recipes.rank(Recipes.Kind.ALCH, d, filters(), -1, id -> id == 1 ? 65 : 0, NOW).get(0);
		assertEquals(5, x.batches);
	}

	// ---------- price drops ----------

	@Test
	public void priceDropAgainstTheHourlyAverage()
	{
		Prices p = new Prices().add(WHIP, "Abyssal whip", 1_500_000, 1_600_000, 70, null);
		PriceData d = p.build();
		assertNull(Alerts.dump(d, WHIP, 10, NOW));
		p.latest.get(WHIP).low = 1_350_000L; // exactly 10% under
		assertNotNull(Alerts.dump(p.build(), WHIP, 10, NOW));
		assertNull("needs 11%", Alerts.dump(p.build(), WHIP, 11, NOW));
		// An old price isn't a drop happening now.
		p.latest.get(WHIP).lowTime = NOW - 3600;
		assertNull(Alerts.dump(p.build(), WHIP, 10, NOW));
	}

